insert into public.services ("id", "slug", "icon", "image_id", "featured", "sort_order", "status", "title_ar", "title_en", "description_ar", "description_en", "details_ar", "details_en")
select "id", "slug", "icon", "image_id", "featured", "sort_order", "status", "title_ar", "title_en", "description_ar", "description_en", "details_ar", "details_en" from jsonb_populate_recordset(null::public.services, $cms_seed$[{"id":"239300f8-25fb-59e1-990a-c39a61d52d39","slug":"knee-joint-pain","icon":"bone","image_id":"f927acae-1401-59dd-a998-219f584dda29","featured":true,"sort_order":1,"status":"published","title_ar":"علاج آلام الركبة والمفاصل","title_en":"Knee and Joint Pain Treatment","description_ar":"تقييم أسباب ألم الركبة والمفاصل وتحديد خطة علاج مناسبة لطبيعة الحالة ونمط الحياة.","description_en":"Assessing the causes of knee and joint pain and building a treatment plan that suits the condition and your lifestyle.","details_ar":{"lead":"ألم الركبة من أكثر شكاوى العظام شيوعًا، وأسبابه متعددة: من الإجهاد والإصابات إلى خشونة المفصل والتهاب الأوتار. الخطوة الأولى دائمًا هي تحديد السبب بدقة قبل اختيار العلاج.","sections":[{"title":"نظرة عامة","icon":"info","paragraphs":["يبدأ التقييم بالاستماع إلى قصة الشكوى: متى بدأ الألم، وما الذي يزيده أو يخففه، وهل صاحبه تورّم أو طقطقة أو شعور بعدم الثبات.","بعد الفحص السريري قد يُطلب تصوير بالأشعة العادية أو بالرنين المغناطيسي عند الحاجة، ثم توضع خطة علاج تناسب طبيعة الحالة ونشاطك اليومي."]},{"title":"متى تحتاج إلى هذه الخدمة؟","icon":"listChecks","items":["ألم في الركبة يستمر أكثر من أسبوعين أو يتكرر مع الحركة","تورّم أو سخونة حول المفصل","صعوبة في صعود السلم أو في الجلوس والقيام","شعور بعدم ثبات الركبة أو انغلاقها أثناء الحركة","ألم بعد إصابة أو التواء مفاجئ"]},{"title":"خيارات العلاج المحتملة","icon":"stethoscope","items":["تعديل النشاط وبرنامج تمارين علاجية لتقوية العضلات المحيطة بالمفصل","علاج دوائي لتخفيف الألم والالتهاب وفق تقييم الطبيب","جلسات علاج طبيعي وتأهيل","حقن موضعية في حالات مختارة","مناقشة الخيارات الجراحية عندما لا تكفي الوسائل التحفظية أو تستدعي الإصابة ذلك"]},{"title":"التعافي والمتابعة","icon":"repeat","paragraphs":["تختلف مدة التعافي باختلاف السبب والعلاج المختار؛ فكثير من حالات الإجهاد تتحسن خلال أسابيع مع الالتزام بالتمارين، بينما تحتاج الإصابات والإجراءات الجراحية إلى برنامج تأهيل أطول."],"items":["مواعيد متابعة لتقييم التحسن وتعديل الخطة","عودة تدريجية إلى النشاط والرياضة","نصائح للحفاظ على وزن صحي وحماية المفصل"]}]},"details_en":{"lead":"Knee pain is one of the most common orthopedic complaints, and it has many possible causes — from overuse and injury to joint wear and tendon inflammation. The first step is always to pinpoint the cause before choosing a treatment.","sections":[{"title":"Overview","icon":"info","paragraphs":["The assessment starts with your story: when the pain began, what makes it better or worse, and whether it comes with swelling, clicking or a sense of instability.","After the clinical examination, plain X-rays or an MRI may be requested when needed, and a treatment plan is then shaped around the nature of your condition and your daily activity."]},{"title":"When you may need this service","icon":"listChecks","items":["Knee pain that lasts more than two weeks or keeps returning with movement","Swelling or warmth around the joint","Difficulty climbing stairs or getting up from a chair","A feeling that the knee gives way or locks as you move","Pain after a sudden injury or twist"]},{"title":"Possible treatment options","icon":"stethoscope","items":["Activity changes and a therapeutic exercise program to strengthen the muscles around the joint","Medication to ease pain and inflammation, as assessed by the doctor","Physiotherapy and rehabilitation sessions","Joint injections in selected cases","Discussing surgical options when conservative care isn't enough or the injury calls for it"]},{"title":"Recovery and follow-up","icon":"repeat","paragraphs":["Recovery time depends on the cause and the treatment chosen. Many overuse problems improve within weeks with consistent exercise, while injuries and surgical procedures need a longer rehabilitation program."],"items":["Follow-up visits to review progress and adjust the plan","A gradual return to activity and sport","Advice on keeping a healthy weight and protecting the joint"]}]}},{"id":"1d784415-a137-5e3d-8422-1ca3021bf58c","slug":"spine-back-pain","icon":"spine","image_id":"dbde6e85-4847-5978-95c1-fc12256849e0","featured":true,"sort_order":2,"status":"published","title_ar":"آلام الظهر والرقبة","title_en":"Back and Neck Pain","description_ar":"فحص مشكلات العمود الفقري والظهر والرقبة، والتمييز بين أسبابها لاختيار العلاج الأنسب.","description_en":"Examining problems of the spine, back and neck, and telling their causes apart to choose the most suitable treatment.","details_ar":{"lead":"قد تنتج آلام الظهر والرقبة عن إجهاد العضلات أو وضعيات الجلوس الخاطئة، وقد ترتبط أحيانًا بمشكلات في الغضاريف أو الفقرات. التمييز بين هذه الأسباب هو مفتاح العلاج الصحيح.","sections":[{"title":"نظرة عامة","icon":"info","paragraphs":["يشمل التقييم فحص حركة العمود الفقري وقوة العضلات والإحساس وردود الأفعال العصبية، لمعرفة ما إذا كان الألم عضليًا أم مرتبطًا بضغط على الأعصاب.","تتحسن معظم حالات آلام الظهر بالعلاج التحفظي، ويُلجأ إلى الفحوصات المتقدمة عند وجود علامات تستدعي ذلك."]},{"title":"متى تحتاج إلى هذه الخدمة؟","icon":"listChecks","items":["ألم في الظهر أو الرقبة يستمر لأكثر من بضعة أسابيع","ألم يمتد إلى الذراع أو الساق","تنميل أو ضعف في الأطراف","ألم يوقظك من النوم أو يزداد ليلًا","ألم بعد سقوط أو إصابة"]},{"title":"خيارات العلاج المحتملة","icon":"stethoscope","items":["تمارين علاجية لتقوية عضلات الظهر والبطن وتحسين المرونة","تصحيح وضعيات الجلوس والعمل","علاج دوائي لتخفيف الألم والتقلصات","جلسات علاج طبيعي","مناقشة التدخل الجراحي في حالات الضغط العصبي التي لا تستجيب للعلاج"]},{"title":"التعافي والمتابعة","icon":"repeat","paragraphs":["يتحسن كثير من المرضى تدريجيًا خلال أسابيع مع الالتزام بالخطة العلاجية، ويساعد الاستمرار في التمارين على تقليل فرص عودة الألم."],"items":["متابعة دورية لتقييم الألم والحركة","برنامج تمارين منزلي","نصائح لبيئة عمل صحية"]}]},"details_en":{"lead":"Back and neck pain can come from muscle strain or poor posture, and is sometimes linked to problems with the discs or vertebrae. Telling these causes apart is the key to the right treatment.","sections":[{"title":"Overview","icon":"info","paragraphs":["The assessment checks spinal movement, muscle strength, sensation and reflexes to find out whether the pain is muscular or related to pressure on a nerve.","Most back pain improves with conservative treatment; advanced imaging is reserved for signs that call for it."]},{"title":"When you may need this service","icon":"listChecks","items":["Back or neck pain lasting more than a few weeks","Pain that spreads into the arm or leg","Numbness or weakness in the arms or legs","Pain that wakes you at night or gets worse at night","Pain after a fall or injury"]},{"title":"Possible treatment options","icon":"stethoscope","items":["Therapeutic exercises to strengthen the back and core and improve flexibility","Correcting sitting and working postures","Medication to relieve pain and muscle spasm","Physiotherapy sessions","Discussing surgery for nerve compression that doesn't respond to treatment"]},{"title":"Recovery and follow-up","icon":"repeat","paragraphs":["Many patients improve gradually over a few weeks when they follow their treatment plan, and keeping up the exercises helps reduce the chance of the pain coming back."],"items":["Regular follow-up of pain and movement","A home exercise program","Advice on a healthy work setup"]}]}},{"id":"f2321bc9-07ef-5641-ba4b-f1e654480e3f","slug":"sports-injuries","icon":"activity","image_id":"f5f65e50-6f13-513c-8e09-10c7bc274531","featured":true,"sort_order":3,"status":"published","title_ar":"إصابات الملاعب","title_en":"Sports Injuries","description_ar":"متابعة الإصابات الرياضية من التشخيص حتى العودة التدريجية الآمنة إلى النشاط.","description_en":"Caring for sports injuries from diagnosis through a gradual, safe return to activity.","details_ar":{"lead":"تشمل إصابات الملاعب الالتواءات وتمزقات العضلات والأربطة وإصابات الغضاريف، والتعامل الصحيح معها منذ البداية يساعد على العودة الآمنة إلى النشاط.","sections":[{"title":"نظرة عامة","icon":"info","paragraphs":["يركز التقييم على طريقة حدوث الإصابة ودرجة ثبات المفصل وقوة العضلات، مع طلب التصوير المناسب عند الحاجة لتحديد نوع الإصابة ودرجتها.","تُبنى الخطة حول هدفك الرياضي: العودة إلى الملعب بأمان وتقليل احتمال تكرار الإصابة."]},{"title":"متى تحتاج إلى هذه الخدمة؟","icon":"listChecks","items":["ألم مفاجئ أثناء التمرين أو المباراة","تورّم سريع أو كدمات بعد الإصابة","صعوبة في تحميل الوزن على الطرف المصاب","شعور بعدم ثبات المفصل أو انزلاقه","ألم يتكرر مع العودة إلى التمرين"]},{"title":"خيارات العلاج المحتملة","icon":"stethoscope","items":["الإسعافات الأولية والراحة النسبية في المرحلة الحادة","تثبيت مؤقت بدعامة عند الحاجة","برنامج تأهيل تدريجي لاستعادة القوة والمرونة","تمارين التوازن والتحكم الحركي","مناقشة الخيار الجراحي لبعض إصابات الأربطة أو الغضاريف"]},{"title":"التعافي والمتابعة","icon":"repeat","paragraphs":["تنقسم العودة إلى الرياضة إلى مراحل واضحة، ولا يُنتقل من مرحلة إلى أخرى إلا بعد تحقيق أهداف محددة للقوة والحركة."],"items":["اختبارات وظيفية قبل العودة إلى المنافسة","تمارين وقائية للإحماء والتقوية","متابعة لتعديل الأحمال التدريبية"]}]},"details_en":{"lead":"Sports injuries include sprains, muscle and ligament tears and cartilage injuries. Handling them correctly from the start supports a safe return to activity.","sections":[{"title":"Overview","icon":"info","paragraphs":["The assessment focuses on how the injury happened, how stable the joint is and how strong the muscles are, with suitable imaging when needed to identify the type and grade of injury.","The plan is built around your sporting goal: getting back to play safely while reducing the risk of re-injury."]},{"title":"When you may need this service","icon":"listChecks","items":["Sudden pain during training or a match","Rapid swelling or bruising after the injury","Difficulty putting weight on the injured limb","A feeling that the joint is unstable or slipping","Pain that keeps returning when you go back to training"]},{"title":"Possible treatment options","icon":"stethoscope","items":["First aid and relative rest in the early phase","Temporary support with a brace when needed","A gradual rehabilitation program to restore strength and flexibility","Balance and movement-control exercises","Discussing surgery for certain ligament or cartilage injuries"]},{"title":"Recovery and follow-up","icon":"repeat","paragraphs":["The return to sport is divided into clear stages, and you only move on to the next stage once specific strength and movement targets are met."],"items":["Functional tests before returning to competition","Injury-prevention warm-up and strengthening exercises","Follow-up to adjust training loads"]}]}},{"id":"d8fc90f1-eeb6-5838-b69c-b881fef7922f","slug":"fractures","icon":"boneFracture","image_id":"9ec378fb-45ea-5d30-bdcd-19376e202eda","featured":true,"sort_order":4,"status":"published","title_ar":"تشخيص وعلاج الكسور","title_en":"Fracture Diagnosis and Treatment","description_ar":"التعامل مع الكسور والإصابات العظمية ومتابعة مراحل الالتئام خطوة بخطوة.","description_en":"Managing fractures and bone injuries, and following each stage of healing step by step.","details_ar":{"lead":"تختلف الكسور في نوعها وموقعها وشدتها، ويعتمد علاجها على ثبات الكسر وعمر المريض وحالته العامة، بهدف التئام العظم في وضعه الصحيح واستعادة الوظيفة.","sections":[{"title":"نظرة عامة","icon":"info","paragraphs":["يبدأ التعامل مع الكسر بالفحص وتقييم الدورة الدموية والأعصاب حول الإصابة، ثم الأشعة لتحديد نوع الكسر ومدى إزاحته.","بعض الكسور يكفيها التثبيت بالجبيرة، بينما تحتاج كسور أخرى إلى رد وتثبيت جراحي بحسب تقييم الطبيب."]},{"title":"متى تحتاج إلى هذه الخدمة؟","icon":"listChecks","items":["ألم شديد بعد سقوط أو حادث","تشوّه واضح أو تورّم سريع في الطرف","صعوبة في تحريك الطرف أو تحميل الوزن عليه","ألم مستمر في عظمة بعد مجهود متكرر (كسور الإجهاد)"]},{"title":"خيارات العلاج المحتملة","icon":"stethoscope","items":["تثبيت الكسر بالجبيرة أو الدعامة","رد الكسر إلى وضعه الصحيح عند الحاجة","التثبيت الجراحي للكسور غير المستقرة","علاج الألم ومتابعة الالتئام بالأشعة"]},{"title":"التعافي والمتابعة","icon":"repeat","paragraphs":["يستغرق التئام العظام عادةً عدة أسابيع ويختلف بحسب نوع الكسر وموقعه وعمر المريض، ويلي ذلك برنامج تأهيل لاستعادة الحركة والقوة."],"items":["أشعة متابعة للتأكد من الالتئام","تمارين لاستعادة مدى الحركة بعد فك التثبيت","إرشادات للتغذية الداعمة لصحة العظام"]}]},"details_en":{"lead":"Fractures vary in type, location and severity. Treatment depends on how stable the fracture is and on the patient's age and general health, with the aim of healing the bone in the right position and restoring function.","sections":[{"title":"Overview","icon":"info","paragraphs":["Fracture care begins with an examination that checks the circulation and nerves around the injury, followed by X-rays to identify the type of fracture and how far the bone has shifted.","Some fractures only need a cast, while others need to be realigned and fixed surgically, as assessed by the doctor."]},{"title":"When you may need this service","icon":"listChecks","items":["Severe pain after a fall or accident","An obvious deformity or rapid swelling of the limb","Difficulty moving the limb or putting weight on it","Persistent pain in a bone after repetitive strain (stress fractures)"]},{"title":"Possible treatment options","icon":"stethoscope","items":["Immobilizing the fracture with a cast or brace","Realigning the fracture (reduction) when needed","Surgical fixation for unstable fractures","Pain relief and follow-up X-rays to monitor healing"]},{"title":"Recovery and follow-up","icon":"repeat","paragraphs":["Bones usually take several weeks to heal, depending on the type and location of the fracture and the patient's age. A rehabilitation program then helps restore movement and strength."],"items":["Follow-up X-rays to confirm healing","Exercises to restore range of motion once the cast comes off","Nutrition advice to support bone health"]}]}},{"id":"747baab6-9118-5ce3-84eb-df4fd0b53b17","slug":"shoulder-pain","icon":"shoulder","image_id":"2f2ab05d-7080-53d2-9628-fc6e47e79095","featured":false,"sort_order":5,"status":"published","title_ar":"آلام الكتف","title_en":"Shoulder Pain","description_ar":"تقييم محدودية حركة الكتف والألم المصاحب لها وتحديد الخيارات العلاجية.","description_en":"Assessing stiffness and pain in the shoulder and setting out the treatment options.","details_ar":{"lead":"الكتف من أكثر مفاصل الجسم حركة، لذلك يتعرض لمشكلات مثل التهاب الأوتار وإصابات الكفة المدوّرة وتيبّس الكتف. التشخيص الدقيق يحدد العلاج الأنسب.","sections":[{"title":"نظرة عامة","icon":"info","paragraphs":["يشمل الفحص تقييم مدى الحركة والقوة في اتجاهات مختلفة، واختبارات خاصة للأوتار والأربطة.","يُطلب التصوير بالموجات الصوتية أو بالرنين المغناطيسي عند الحاجة لتقييم الأوتار والأنسجة الرخوة."]},{"title":"متى تحتاج إلى هذه الخدمة؟","icon":"listChecks","items":["ألم عند رفع الذراع أو النوم على الكتف","محدودية تدريجية في حركة الكتف","ضعف عند رفع الأشياء","ألم بعد إصابة أو خلع سابق"]},{"title":"خيارات العلاج المحتملة","icon":"stethoscope","items":["تمارين علاجية لاستعادة الحركة وتقوية العضلات","علاج دوائي لتخفيف الألم والالتهاب","حقن موضعية في حالات مختارة","مناقشة الخيار الجراحي لبعض إصابات الأوتار أو حالات عدم الثبات"]},{"title":"التعافي والمتابعة","icon":"repeat","paragraphs":["يحتاج الكتف غالبًا إلى برنامج تأهيل منتظم، وقد يستغرق التحسن الكامل وقتًا أطول من بعض المفاصل الأخرى، لذلك يعد الالتزام بالتمارين عنصرًا أساسيًا."],"items":["تمارين منزلية يومية","متابعة لقياس تحسن مدى الحركة","عودة تدريجية إلى الأنشطة فوق مستوى الرأس"]}]},"details_en":{"lead":"The shoulder is one of the most mobile joints in the body, which makes it prone to problems such as tendinitis, rotator cuff injuries and frozen shoulder. An accurate diagnosis determines the right treatment.","sections":[{"title":"Overview","icon":"info","paragraphs":["The examination assesses range of motion and strength in different directions, along with specific tests for the tendons and ligaments.","An ultrasound or MRI may be requested when needed to assess the tendons and soft tissues."]},{"title":"When you may need this service","icon":"listChecks","items":["Pain when you raise your arm or lie on your shoulder","A gradual loss of shoulder movement","Weakness when lifting objects","Pain after a previous injury or dislocation"]},{"title":"Possible treatment options","icon":"stethoscope","items":["Therapeutic exercises to restore movement and strengthen the muscles","Medication to ease pain and inflammation","Joint injections in selected cases","Discussing surgery for certain tendon injuries or instability"]},{"title":"Recovery and follow-up","icon":"repeat","paragraphs":["The shoulder usually needs a regular rehabilitation program, and full improvement can take longer than in some other joints — so sticking with the exercises is essential."],"items":["Daily home exercises","Follow-up to measure gains in range of motion","A gradual return to overhead activities"]}]}},{"id":"b1c17abd-070a-5f41-bc15-a876b6b23fec","slug":"osteoarthritis","icon":"personStanding","image_id":"ebb29b4f-49cc-5cf3-b5cb-24cc0c6c1ea4","featured":false,"sort_order":6,"status":"published","title_ar":"خشونة المفاصل","title_en":"Osteoarthritis","description_ar":"خطة متكاملة للتعامل مع خشونة المفاصل وتخفيف أثرها على الحركة اليومية.","description_en":"A complete plan for managing osteoarthritis and reducing its impact on everyday movement.","details_ar":{"lead":"خشونة المفاصل حالة مزمنة تتآكل فيها الغضاريف تدريجيًا، ويمكن بالتشخيص المبكر والخطة المناسبة تخفيف الألم وتحسين الحركة والحفاظ على جودة الحياة.","sections":[{"title":"نظرة عامة","icon":"info","paragraphs":["تصيب الخشونة غالبًا مفاصل الركبة والحوض واليدين والعمود الفقري، وتزداد مع التقدم في العمر أو زيادة الوزن أو الإصابات السابقة.","يعتمد التشخيص على الأعراض والفحص السريري والأشعة، ويُحدَّد العلاج بحسب درجة الخشونة وتأثيرها على حياتك اليومية."]},{"title":"متى تحتاج إلى هذه الخدمة؟","icon":"listChecks","items":["ألم في المفصل يزداد مع المجهود ويخف مع الراحة","تيبّس صباحي أو بعد الجلوس لفترة","طقطقة أو احتكاك عند الحركة","تراجع تدريجي في القدرة على المشي أو صعود السلم"]},{"title":"خيارات العلاج المحتملة","icon":"stethoscope","items":["تمارين تقوية وتحسين المرونة","التحكم في الوزن لتخفيف الحمل على المفاصل","علاج دوائي لتخفيف الألم","حقن المفصل في حالات مختارة","مناقشة الخيارات الجراحية في المراحل المتقدمة"]},{"title":"التعافي والمتابعة","icon":"repeat","paragraphs":["تحتاج الخشونة إلى متابعة طويلة المدى، والهدف هو السيطرة على الأعراض والحفاظ على الحركة، مع تعديل الخطة كلما تغيرت احتياجاتك."],"items":["متابعة دورية لتقييم الأعراض","برنامج نشاط بدني مناسب","أدوات مساعدة عند الحاجة لتخفيف الحمل"]}]},"details_en":{"lead":"Osteoarthritis is a long-term condition in which joint cartilage gradually wears down. With early diagnosis and the right plan, pain can be eased, movement improved and quality of life maintained.","sections":[{"title":"Overview","icon":"info","paragraphs":["It most often affects the knees, hips, hands and spine, and becomes more common with age, excess weight or previous injuries.","Diagnosis is based on your symptoms, the clinical examination and X-rays, and treatment depends on how advanced the condition is and how it affects your daily life."]},{"title":"When you may need this service","icon":"listChecks","items":["Joint pain that worsens with activity and eases with rest","Stiffness in the morning or after sitting for a while","Grinding or crackling when the joint moves","A gradual decline in your ability to walk or climb stairs"]},{"title":"Possible treatment options","icon":"stethoscope","items":["Strengthening and flexibility exercises","Weight management to reduce the load on the joints","Pain-relief medication","Joint injections in selected cases","Discussing surgical options at advanced stages"]},{"title":"Recovery and follow-up","icon":"repeat","paragraphs":["Osteoarthritis needs long-term follow-up. The aim is to control symptoms and preserve movement, adjusting the plan as your needs change."],"items":["Regular follow-up of your symptoms","A suitable physical activity program","Walking aids when needed to reduce the load"]}]}},{"id":"2263c70d-6c34-551c-a539-2d1796a32153","slug":"hand-wrist","icon":"hand","image_id":"218a912f-49a2-5879-b777-fe0104bd6da5","featured":false,"sort_order":7,"status":"published","title_ar":"اليد والرسغ","title_en":"Hand and Wrist","description_ar":"تشخيص آلام اليد والرسغ والأصابع ومتابعة استعادة وظيفتها.","description_en":"Diagnosing pain in the hand, wrist and fingers, and following the recovery of their function.","details_ar":{"lead":"تؤثر مشكلات اليد والرسغ مباشرة في الأعمال اليومية، ومنها متلازمة النفق الرسغي والتهاب الأوتار والكسور وإصابات الأربطة.","sections":[{"title":"نظرة عامة","icon":"info","paragraphs":["يشمل التقييم فحص الإحساس وقوة القبضة وحركة الأصابع والرسغ، ويُطلب رسم الأعصاب أو التصوير عند الحاجة.","تُصمَّم الخطة لاستعادة وظيفة اليد في العمل والحياة اليومية."]},{"title":"متى تحتاج إلى هذه الخدمة؟","icon":"listChecks","items":["تنميل أو وخز في الأصابع، خاصة ليلًا","ضعف في القبضة أو سقوط الأشياء من اليد","ألم أو تورّم في الرسغ بعد سقوط","ألم مع حركة الإبهام أو الأصابع","انغلاق الإصبع أو صعوبة فرده"]},{"title":"خيارات العلاج المحتملة","icon":"stethoscope","items":["جبيرة أو دعامة ليلية","تعديل الأنشطة المسببة للإجهاد","تمارين علاجية لليد","حقن موضعية في حالات مختارة","مناقشة التدخل الجراحي عند الحاجة"]},{"title":"التعافي والمتابعة","icon":"repeat","paragraphs":["تتحسن كثير من حالات اليد والرسغ بالعلاج التحفظي، وتحتاج الحالات الجراحية إلى تأهيل لاستعادة الحركة والقوة."],"items":["تمارين يومية لليد","متابعة لتقييم الإحساس والقوة","نصائح لبيئة عمل مريحة لليدين"]}]},"details_en":{"lead":"Hand and wrist problems directly affect everyday tasks. They include carpal tunnel syndrome, tendinitis, fractures and ligament injuries.","sections":[{"title":"Overview","icon":"info","paragraphs":["The assessment checks sensation, grip strength and the movement of the fingers and wrist, with nerve conduction studies or imaging requested when needed.","The plan is designed to restore the function of your hand at work and in daily life."]},{"title":"When you may need this service","icon":"listChecks","items":["Numbness or tingling in the fingers, especially at night","A weak grip or dropping objects","Wrist pain or swelling after a fall","Pain when moving the thumb or fingers","A finger that locks or is hard to straighten"]},{"title":"Possible treatment options","icon":"stethoscope","items":["A splint or night brace","Changing the activities that strain the hand","Hand therapy exercises","Local injections in selected cases","Discussing surgery when needed"]},{"title":"Recovery and follow-up","icon":"repeat","paragraphs":["Many hand and wrist problems improve with conservative treatment, while surgical cases need rehabilitation to restore movement and strength."],"items":["Daily hand exercises","Follow-up of sensation and strength","Advice on a hand-friendly work setup"]}]}},{"id":"24c2f370-ac68-5bd3-84a9-41f73b15ce09","slug":"foot-ankle","icon":"footprints","image_id":"4ce8320a-1a67-5a9b-82a0-e448852e77bc","featured":false,"sort_order":8,"status":"published","title_ar":"القدم والكاحل","title_en":"Foot and Ankle","description_ar":"علاج آلام القدم والكاحل والالتواءات المتكررة وتحسين الثبات أثناء الحركة.","description_en":"Treating foot and ankle pain and recurrent sprains, and improving stability as you move.","details_ar":{"lead":"تحمل القدم والكاحل وزن الجسم في كل خطوة، لذلك تؤثر مشكلاتهما — مثل الالتواءات المتكررة وآلام الكعب والتهاب الأوتار — في الحركة اليومية بشكل كبير.","sections":[{"title":"نظرة عامة","icon":"info","paragraphs":["يقيّم الفحص طريقة المشي وشكل القدم وثبات الكاحل ومواضع الألم، مع التصوير عند الحاجة.","تهدف الخطة إلى تخفيف الألم وتحسين الثبات وتقليل احتمال تكرار الإصابة."]},{"title":"متى تحتاج إلى هذه الخدمة؟","icon":"listChecks","items":["ألم في الكعب، خاصة مع أولى خطوات الصباح","التواءات متكررة في الكاحل","تورّم مستمر بعد إصابة","ألم يزداد مع المشي أو الوقوف لفترات طويلة","تغيّر في شكل القدم أو الأصابع"]},{"title":"خيارات العلاج المحتملة","icon":"stethoscope","items":["تمارين الإطالة والتقوية","اختيار الحذاء المناسب ودعامات القدم","تثبيت مؤقت بدعامة للكاحل","علاج دوائي لتخفيف الألم","مناقشة التدخل الجراحي في حالات عدم الثبات المزمن أو الإصابات الشديدة"]},{"title":"التعافي والمتابعة","icon":"repeat","paragraphs":["يتحسن معظم المرضى تدريجيًا مع الالتزام بالتمارين والحذاء المناسب، وتحتاج إصابات الأربطة إلى تمارين توازن لتقليل تكرار الالتواء."],"items":["تمارين توازن وثبات","عودة تدريجية إلى المشي والرياضة","متابعة لتقييم التحسن"]}]},"details_en":{"lead":"Your feet and ankles carry your body weight with every step, so problems such as recurrent sprains, heel pain and tendinitis have a big impact on daily movement.","sections":[{"title":"Overview","icon":"info","paragraphs":["The examination looks at how you walk, the shape of your foot, the stability of your ankle and where the pain is, with imaging when needed.","The plan aims to ease pain, improve stability and reduce the chance of the injury coming back."]},{"title":"When you may need this service","icon":"listChecks","items":["Heel pain, especially with your first steps in the morning","Repeated ankle sprains","Swelling that persists after an injury","Pain that worsens with walking or long periods of standing","A change in the shape of the foot or toes"]},{"title":"Possible treatment options","icon":"stethoscope","items":["Stretching and strengthening exercises","Choosing suitable footwear and foot supports","Temporary support with an ankle brace","Pain-relief medication","Discussing surgery for chronic instability or severe injuries"]},{"title":"Recovery and follow-up","icon":"repeat","paragraphs":["Most patients improve gradually with regular exercise and suitable footwear, and ligament injuries need balance training to reduce repeat sprains."],"items":["Balance and stability exercises","A gradual return to walking and sport","Follow-up to review progress"]}]}}]$cms_seed$::jsonb)
