insert into public.conditions ("id", "slug", "icon", "image_id", "featured", "sort_order", "status", "title_ar", "title_en", "excerpt_ar", "excerpt_en", "symptoms_ar", "symptoms_en", "details_ar", "details_en")
select "id", "slug", "icon", "image_id", "featured", "sort_order", "status", "title_ar", "title_en", "excerpt_ar", "excerpt_en", "symptoms_ar", "symptoms_en", "details_ar", "details_en" from jsonb_populate_recordset(null::public.conditions, $cms_seed$[{"id":"cf8563c9-b574-50de-a109-7932637e8468","slug":"joint-pain","icon":"bone","image_id":"e55454ff-9a2c-5603-912d-da51c843f3cb","featured":true,"sort_order":1,"status":"published","title_ar":"آلام المفاصل","title_en":"Joint Pain","excerpt_ar":"ألم مستمر أو متكرر في مفصل أو أكثر يؤثر على الحركة أو النوم، ويحتاج إلى تقييم لمعرفة سببه.","excerpt_en":"Ongoing or recurring pain in one or more joints that affects movement or sleep and needs an assessment to find its cause.","symptoms_ar":["ألم عند الحركة","تورّم أو احمرار","طقطقة مزعجة"],"symptoms_en":["Pain with movement","Swelling or redness","Troublesome clicking"],"details_ar":{"lead":"آلام المفاصل عرَض شائع قد ينتج عن إجهاد أو إصابة أو التهاب أو خشونة، ومعرفة السبب هي الخطوة الأهم لاختيار العلاج المناسب.","sections":[{"title":"نظرة عامة","icon":"info","paragraphs":["قد يصيب الألم مفصلًا واحدًا أو عدة مفاصل، وقد يكون مؤقتًا بعد مجهود أو مستمرًا يؤثر على الحركة والنوم.","يساعد وصف طبيعة الألم وتوقيته وما يصاحبه من أعراض على توجيه الفحص والوصول إلى التشخيص."]},{"title":"الأسباب المحتملة","icon":"searchCheck","items":["الإجهاد أو الاستخدام المتكرر للمفصل","الإصابات والالتواءات","خشونة المفاصل","التهاب الأوتار أو الأكياس الزلالية","أمراض التهابية تحتاج إلى تقييم متخصص"]},{"title":"متى تزور الطبيب؟","icon":"alertCircle","items":["ألم يستمر أكثر من أسبوعين","تورّم أو احمرار أو سخونة في المفصل","ألم يمنعك من الحركة أو النوم","ألم مصحوب بحرارة أو إعياء عام"]},{"title":"التشخيص والعلاج","icon":"clipboardCheck","paragraphs":["يعتمد العلاج على السبب؛ وقد يشمل الراحة النسبية والتمارين العلاجية والأدوية المناسبة، مع متابعة منتظمة للتأكد من التحسن."]}]},"details_en":{"lead":"Joint pain is a common symptom that can come from overuse, injury, inflammation or wear — and finding the cause is the most important step in choosing the right treatment.","sections":[{"title":"Overview","icon":"info","paragraphs":["The pain may affect one joint or several. It can be short-lived after exertion, or persistent enough to affect movement and sleep.","Describing what the pain feels like, when it happens and what comes with it helps guide the examination and the diagnosis."]},{"title":"Possible causes","icon":"searchCheck","items":["Overuse or repetitive strain on the joint","Injuries and sprains","Osteoarthritis","Inflammation of the tendons or bursae","Inflammatory conditions that need specialist assessment"]},{"title":"When to see a doctor","icon":"alertCircle","items":["Pain lasting more than two weeks","Swelling, redness or warmth in the joint","Pain that stops you moving or sleeping","Pain together with fever or general fatigue"]},{"title":"Diagnosis and treatment","icon":"clipboardCheck","paragraphs":["Treatment depends on the cause. It may include relative rest, therapeutic exercise and suitable medication, with regular follow-up to make sure you are improving."]}]}},{"id":"f10372fb-7a26-525e-afc7-da6e592a4c05","slug":"back-pain","icon":"spine","image_id":"dd300754-b402-5493-8dee-977007cd98e3","featured":true,"sort_order":2,"status":"published","title_ar":"آلام الظهر","title_en":"Back Pain","excerpt_ar":"ألم أسفل الظهر أو أعلاه يستمر لأيام أو يمتد إلى الساق، خاصة إذا صاحبه تنميل أو ضعف.","excerpt_en":"Pain in the lower or upper back that lasts for days or spreads down the leg — especially with numbness or weakness.","symptoms_ar":["ألم ممتد للساق","تنميل","صعوبة في الانحناء"],"symptoms_en":["Pain spreading down the leg","Numbness","Difficulty bending"],"details_ar":{"lead":"ألم الظهر من أكثر أسباب زيارة طبيب العظام شيوعًا، ومعظم حالاته بسيطة وتتحسن، لكن بعض العلامات تستدعي تقييمًا سريعًا.","sections":[{"title":"نظرة عامة","icon":"info","paragraphs":["قد يكون الألم في أسفل الظهر أو أعلاه، وقد يمتد إلى الساقين إذا كان مرتبطًا بتهيّج الأعصاب.","تؤدي وضعيات الجلوس والعمل ومستوى النشاط البدني دورًا كبيرًا في ظهور الألم وتكراره."]},{"title":"الأسباب المحتملة","icon":"searchCheck","items":["شد أو إجهاد عضلي","وضعيات جلوس خاطئة لفترات طويلة","الانزلاق الغضروفي","خشونة الفقرات","حمل الأوزان بطريقة غير صحيحة"]},{"title":"متى تزور الطبيب؟","icon":"alertCircle","items":["ألم يمتد إلى الساق مع تنميل أو ضعف","ألم بعد سقوط أو حادث","ألم يزداد ليلًا أو مع الراحة","صعوبة في التحكم في البول أو البراز — تستدعي التوجه إلى الطوارئ فورًا"]},{"title":"التشخيص والعلاج","icon":"clipboardCheck","paragraphs":["يبدأ العلاج عادةً بوسائل تحفظية تشمل التمارين وتعديل الأنشطة والأدوية المناسبة، ويُلجأ إلى الفحوصات المتقدمة عند وجود علامات عصبية أو عدم التحسن."]}]},"details_en":{"lead":"Back pain is one of the most common reasons to see an orthopedic doctor. Most cases are minor and improve, but some warning signs call for a prompt assessment.","sections":[{"title":"Overview","icon":"info","paragraphs":["The pain may be in the lower or upper back, and it can spread to the legs when it is linked to an irritated nerve.","How you sit and work, and how active you are, play a big part in how back pain starts and whether it returns."]},{"title":"Possible causes","icon":"searchCheck","items":["Muscle strain or overuse","Sitting in a poor posture for long periods","A herniated disc","Wear and tear in the spine","Lifting heavy objects incorrectly"]},{"title":"When to see a doctor","icon":"alertCircle","items":["Pain spreading to the leg with numbness or weakness","Pain after a fall or accident","Pain that gets worse at night or at rest","Difficulty controlling your bladder or bowels — go to the emergency department immediately"]},{"title":"Diagnosis and treatment","icon":"clipboardCheck","paragraphs":["Treatment usually starts with conservative measures — exercise, adjusting your activities and suitable medication — with further imaging if there are nerve-related signs or no improvement."]}]}},{"id":"2f744850-6c3b-5422-a2b8-95a07071293f","slug":"sports-injuries","icon":"activity","image_id":"1d793e06-347f-5ad6-a5ba-5af0117bae75","featured":true,"sort_order":3,"status":"published","title_ar":"الإصابات الرياضية","title_en":"Sports Injuries","excerpt_ar":"التواءات أو تمزقات أو إصابات مفاجئة أثناء النشاط البدني تحتاج إلى فحص قبل العودة للتمرين.","excerpt_en":"Sprains, tears or sudden injuries during physical activity that should be examined before you return to training.","symptoms_ar":["ألم مفاجئ","عدم ثبات المفصل","كدمات وتورّم"],"symptoms_en":["Sudden pain","Joint instability","Bruising and swelling"],"details_ar":{"lead":"تحدث الإصابات الرياضية نتيجة حركة مفاجئة أو احتكاك أو إجهاد متكرر، والتقييم المبكر يحدد درجة الإصابة ويحمي من تفاقمها.","sections":[{"title":"نظرة عامة","icon":"info","paragraphs":["تشمل الإصابات الشائعة التواء الكاحل وإصابات أربطة الركبة وتمزقات العضلات والتهاب الأوتار.","العودة المبكرة إلى التمرين قبل اكتمال التعافي من أهم أسباب تكرار الإصابة."]},{"title":"الأسباب المحتملة","icon":"searchCheck","items":["الالتواء أو الدوران المفاجئ للمفصل","الاصطدام أو السقوط أثناء اللعب","ضعف الإحماء أو الإجهاد الزائد","زيادة الأحمال التدريبية بسرعة"]},{"title":"متى تزور الطبيب؟","icon":"alertCircle","items":["صعوبة في تحميل الوزن على الطرف","تورّم سريع بعد الإصابة","صوت فرقعة لحظة الإصابة","شعور بعدم ثبات المفصل"]},{"title":"التشخيص والعلاج","icon":"clipboardCheck","paragraphs":["يبدأ التعامل بالإسعافات الأولية ثم التقييم لتحديد نوع الإصابة، ويتبع ذلك برنامج تأهيل تدريجي للعودة الآمنة إلى النشاط."]}]},"details_en":{"lead":"Sports injuries are caused by sudden movements, contact or repetitive strain. An early assessment shows how serious the injury is and helps stop it from getting worse.","sections":[{"title":"Overview","icon":"info","paragraphs":["Common injuries include ankle sprains, knee ligament injuries, muscle tears and tendinitis.","Going back to training before you have fully recovered is one of the main reasons injuries come back."]},{"title":"Possible causes","icon":"searchCheck","items":["A sudden twist or turn of the joint","A collision or fall during play","Too little warm-up or overtraining","Increasing the training load too quickly"]},{"title":"When to see a doctor","icon":"alertCircle","items":["Difficulty putting weight on the limb","Rapid swelling after the injury","A popping sound at the moment of injury","A feeling that the joint is unstable"]},{"title":"Diagnosis and treatment","icon":"clipboardCheck","paragraphs":["Care starts with first aid and an assessment to identify the type of injury, followed by a gradual rehabilitation program for a safe return to activity."]}]}},{"id":"651341c2-4f62-56ad-8824-adfe2f97e845","slug":"stiffness-osteoarthritis","icon":"personStanding","image_id":"36cebc4a-7829-562b-ac6c-8492de1b81ed","featured":true,"sort_order":4,"status":"published","title_ar":"تيبّس وخشونة المفاصل","title_en":"Joint Stiffness and Osteoarthritis","excerpt_ar":"تيبّس صباحي أو محدودية تدريجية في الحركة قد تكون من علامات خشونة المفاصل.","excerpt_en":"Morning stiffness or a gradual loss of movement can be early signs of osteoarthritis.","symptoms_ar":["تيبّس صباحي","محدودية الحركة","ألم مع المجهود"],"symptoms_en":["Morning stiffness","Limited movement","Pain with exertion"],"details_ar":{"lead":"تيبّس المفاصل، خاصة في الصباح، قد يكون من العلامات المبكرة للخشونة، والتعامل المبكر يساعد على الحفاظ على الحركة.","sections":[{"title":"نظرة عامة","icon":"info","paragraphs":["تتطور الخشونة ببطء، وتبدأ غالبًا بتيبّس وألم بعد المجهود، ثم قد تحدّ من الحركة تدريجيًا.","يمكن لنمط الحياة النشط والتمارين المناسبة أن يخففا الأعراض بشكل ملحوظ."]},{"title":"الأسباب المحتملة","icon":"searchCheck","items":["تآكل الغضروف مع التقدم في العمر","زيادة الوزن","إصابات سابقة في المفصل","عوامل وراثية"]},{"title":"متى تزور الطبيب؟","icon":"alertCircle","items":["تيبّس صباحي يتكرر يوميًا","تراجع في مدى حركة المفصل","ألم يؤثر على المشي أو العمل","تورّم متكرر في المفصل"]},{"title":"التشخيص والعلاج","icon":"clipboardCheck","paragraphs":["يركز العلاج على تخفيف الألم وتحسين الحركة من خلال التمارين والتحكم في الوزن والأدوية المناسبة، مع دراسة الخيارات الأخرى في المراحل المتقدمة."]}]},"details_en":{"lead":"Joint stiffness, especially in the morning, can be an early sign of osteoarthritis — and early care helps keep you moving.","sections":[{"title":"Overview","icon":"info","paragraphs":["Osteoarthritis develops slowly. It often begins with stiffness and pain after exertion, and may gradually limit movement.","An active lifestyle and the right exercises can ease the symptoms noticeably."]},{"title":"Possible causes","icon":"searchCheck","items":["Cartilage wear with age","Excess weight","Previous joint injuries","Genetic factors"]},{"title":"When to see a doctor","icon":"alertCircle","items":["Morning stiffness that returns every day","Less movement in the joint than before","Pain that affects walking or work","Swelling in the joint that keeps coming back"]},{"title":"Diagnosis and treatment","icon":"clipboardCheck","paragraphs":["Treatment focuses on easing pain and improving movement through exercise, weight management and suitable medication, with other options considered at advanced stages."]}]}},{"id":"649ac485-28f8-5dbb-a760-202180c0146a","slug":"herniated-disc","icon":"spine","image_id":"6b8c3796-69ab-5678-96eb-db8c759f2bfa","featured":false,"sort_order":5,"status":"published","title_ar":"الانزلاق الغضروفي","title_en":"Herniated Disc","excerpt_ar":"بروز جزء من الغضروف بين الفقرات قد يضغط على الأعصاب ويسبب ألمًا يمتد إلى الذراع أو الساق.","excerpt_en":"Part of a spinal disc bulges between the vertebrae and can press on a nerve, causing pain that spreads to the arm or leg.","symptoms_ar":["ألم ممتد للأطراف","تنميل ووخز","ضعف عضلي"],"symptoms_en":["Pain spreading to the limbs","Numbness and tingling","Muscle weakness"],"details_ar":{"lead":"الانزلاق الغضروفي حالة يبرز فيها جزء من الغضروف الواقع بين الفقرات، وقد يضغط على جذور الأعصاب فيسبب ألمًا ممتدًا وتنميلًا.","sections":[{"title":"نظرة عامة","icon":"info","paragraphs":["يحدث غالبًا في أسفل الظهر أو الرقبة، وتتحسن نسبة كبيرة من الحالات بالعلاج التحفظي خلال أسابيع إلى أشهر.","يحدد الفحص العصبي، والتصوير بالرنين المغناطيسي عند الحاجة، موضع الانزلاق ودرجة تأثيره على الأعصاب."]},{"title":"الأسباب المحتملة","icon":"searchCheck","items":["تغيرات الغضاريف مع التقدم في العمر","حمل الأوزان الثقيلة بطريقة خاطئة","الجلوس لفترات طويلة","زيادة الوزن وضعف عضلات الجذع"]},{"title":"متى تزور الطبيب؟","icon":"alertCircle","items":["ألم ممتد إلى الساق أو الذراع لا يتحسن","تنميل أو ضعف متزايد في الطرف","صعوبة في المشي أو الوقوف","اضطراب في التحكم في البول أو البراز — يستدعي التوجه إلى الطوارئ فورًا"]},{"title":"التشخيص والعلاج","icon":"clipboardCheck","paragraphs":["يبدأ العلاج غالبًا بالأدوية والتمارين العلاجية وتعديل الأنشطة، ويُناقش التدخل الجراحي عند استمرار الضغط العصبي أو ظهور ضعف متزايد."]}]},"details_en":{"lead":"A herniated disc happens when part of the disc between two vertebrae bulges out and may press on a nerve root, causing radiating pain and numbness.","sections":[{"title":"Overview","icon":"info","paragraphs":["It most often occurs in the lower back or neck, and many cases improve with conservative treatment within weeks to months.","A neurological examination — with an MRI when needed — shows where the disc has herniated and how much it affects the nerves."]},{"title":"Possible causes","icon":"searchCheck","items":["Age-related changes in the discs","Lifting heavy objects incorrectly","Sitting for long periods","Excess weight and weak core muscles"]},{"title":"When to see a doctor","icon":"alertCircle","items":["Pain spreading to the leg or arm that doesn't improve","Numbness or weakness in a limb that is getting worse","Difficulty walking or standing","Loss of bladder or bowel control — go to the emergency department immediately"]},{"title":"Diagnosis and treatment","icon":"clipboardCheck","paragraphs":["Treatment usually starts with medication, therapeutic exercise and activity changes. Surgery is discussed if nerve compression persists or weakness increases."]}]}},{"id":"1b82994e-a832-59f2-93ce-3420b6bcde74","slug":"frozen-shoulder","icon":"shoulder","image_id":"88e67efa-2c03-5ea0-a6ca-a561970cfaae","featured":false,"sort_order":6,"status":"published","title_ar":"تيبّس الكتف (الكتف المتجمد)","title_en":"Frozen Shoulder","excerpt_ar":"ألم يتبعه تيبّس تدريجي يحدّ من حركة الكتف في جميع الاتجاهات، ويتحسن عادةً مع الوقت والعلاج المنتظم.","excerpt_en":"Pain followed by gradual stiffness that limits shoulder movement in every direction, and usually improves with time and regular treatment.","symptoms_ar":["ألم ليلي","صعوبة رفع الذراع","محدودية الحركة"],"symptoms_en":["Night pain","Difficulty raising the arm","Limited movement"],"details_ar":{"lead":"تيبّس الكتف، أو ما يُعرف بالكتف المتجمد، حالة يلتهب فيها غلاف المفصل ويتيبّس تدريجيًا، فتقل حركة الكتف ويصاحبها ألم.","sections":[{"title":"نظرة عامة","icon":"info","paragraphs":["تمر الحالة عادةً بمراحل: ألم متزايد، ثم تيبّس، ثم تحسّن تدريجي في الحركة.","تكون أكثر شيوعًا لدى مرضى السكري وبعد فترات طويلة من قلة حركة الكتف."]},{"title":"الأسباب المحتملة","icon":"searchCheck","items":["التهاب محفظة مفصل الكتف","قلة حركة الكتف بعد إصابة أو جراحة","مرض السكري واضطرابات الغدة الدرقية","أسباب غير معروفة في بعض الحالات"]},{"title":"متى تزور الطبيب؟","icon":"alertCircle","items":["ألم في الكتف يمنعك من النوم","صعوبة في تمشيط الشعر أو ارتداء الملابس","تراجع مستمر في حركة الكتف"]},{"title":"التشخيص والعلاج","icon":"clipboardCheck","paragraphs":["يعتمد العلاج على تخفيف الألم واستعادة الحركة تدريجيًا عبر تمارين الإطالة والعلاج الطبيعي، وقد تُستخدم الحقن الموضعية في حالات مختارة."]}]},"details_en":{"lead":"Frozen shoulder (adhesive capsulitis) is a condition in which the lining of the shoulder joint becomes inflamed and gradually stiffens, reducing movement and causing pain.","sections":[{"title":"Overview","icon":"info","paragraphs":["It usually passes through stages: increasing pain, then stiffness, then a gradual return of movement.","It is more common in people with diabetes and after long periods of limited shoulder movement."]},{"title":"Possible causes","icon":"searchCheck","items":["Inflammation of the shoulder joint capsule","Little shoulder movement after an injury or surgery","Diabetes and thyroid disorders","No clear cause in some cases"]},{"title":"When to see a doctor","icon":"alertCircle","items":["Shoulder pain that keeps you from sleeping","Difficulty brushing your hair or getting dressed","Shoulder movement that keeps decreasing"]},{"title":"Diagnosis and treatment","icon":"clipboardCheck","paragraphs":["Treatment aims to ease the pain and restore movement gradually with stretching exercises and physiotherapy; local injections may be used in selected cases."]}]}},{"id":"3080ba91-6d4a-5e16-8cad-cd631120beb7","slug":"carpal-tunnel","icon":"hand","image_id":"74f65535-ab2a-58cc-8dd5-b20de3d136ba","featured":false,"sort_order":7,"status":"published","title_ar":"متلازمة النفق الرسغي","title_en":"Carpal Tunnel Syndrome","excerpt_ar":"ضغط على العصب المتوسط عند الرسغ يسبب تنميلًا في الأصابع وضعفًا في القبضة، ويزداد غالبًا في الليل.","excerpt_en":"Pressure on the median nerve at the wrist that causes numbness in the fingers and a weaker grip, often worse at night.","symptoms_ar":["تنميل الأصابع ليلًا","ضعف القبضة","ألم في الرسغ"],"symptoms_en":["Numb fingers at night","Weak grip","Wrist pain"],"details_ar":{"lead":"تنتج متلازمة النفق الرسغي عن ضغط على العصب المتوسط أثناء مروره في نفق ضيق عند الرسغ، فيسبب تنميلًا وألمًا في اليد.","sections":[{"title":"نظرة عامة","icon":"info","paragraphs":["يشعر المريض غالبًا بتنميل في الإبهام والسبابة والوسطى، وقد يستيقظ ليلًا بسببه.","يساعد الفحص السريري، ورسم الأعصاب عند الحاجة، على تأكيد التشخيص وتحديد درجة الضغط."]},{"title":"الأسباب المحتملة","icon":"searchCheck","items":["الحركات المتكررة لليد والرسغ","الحمل والتغيرات الهرمونية","مرض السكري وقصور الغدة الدرقية","إصابات أو كسور سابقة في الرسغ"]},{"title":"متى تزور الطبيب؟","icon":"alertCircle","items":["تنميل يتكرر أو يوقظك من النوم","ضعف في الإمساك بالأشياء","ضمور في عضلات قاعدة الإبهام"]},{"title":"التشخيص والعلاج","icon":"clipboardCheck","paragraphs":["تبدأ الخطة غالبًا بجبيرة ليلية وتعديل الأنشطة والتمارين، وقد تُستخدم الحقن الموضعية، ويُناقش التدخل الجراحي عند استمرار الأعراض أو شدتها."]}]},"details_en":{"lead":"Carpal tunnel syndrome is caused by pressure on the median nerve as it passes through a narrow tunnel at the wrist, leading to numbness and pain in the hand.","sections":[{"title":"Overview","icon":"info","paragraphs":["People often feel numbness in the thumb, index and middle fingers, and may wake at night because of it.","A clinical examination — with nerve conduction studies when needed — confirms the diagnosis and shows how severe the compression is."]},{"title":"Possible causes","icon":"searchCheck","items":["Repetitive hand and wrist movements","Pregnancy and hormonal changes","Diabetes and an underactive thyroid","Previous wrist injuries or fractures"]},{"title":"When to see a doctor","icon":"alertCircle","items":["Numbness that keeps returning or wakes you up","Weakness when gripping objects","Shrinking of the muscles at the base of the thumb"]},{"title":"Diagnosis and treatment","icon":"clipboardCheck","paragraphs":["The plan usually starts with a night splint, activity changes and exercises. Local injections may be used, and surgery is discussed if symptoms persist or are severe."]}]}},{"id":"49ff83b9-5e1b-5fac-805a-e77e652157cd","slug":"osteoporosis","icon":"bone","image_id":"d2282f1b-b0db-5642-86da-4bcadedda61f","featured":false,"sort_order":8,"status":"published","title_ar":"هشاشة العظام","title_en":"Osteoporosis","excerpt_ar":"نقص تدريجي في كثافة العظام يجعلها أكثر عرضة للكسور، وغالبًا لا تظهر له أعراض قبل حدوث الكسر.","excerpt_en":"A gradual loss of bone density that makes bones more likely to break, often with no symptoms until a fracture happens.","symptoms_ar":["كسور مع إصابات بسيطة","انحناء الظهر","نقص الطول"],"symptoms_en":["Fractures from minor falls","A stooped back","Loss of height"],"details_ar":{"lead":"هشاشة العظام حالة تقل فيها كثافة العظام وتضعف بنيتها، فتزداد قابليتها للكسر حتى مع السقطات البسيطة.","sections":[{"title":"نظرة عامة","icon":"info","paragraphs":["تُسمى أحيانًا «المرض الصامت» لأنها قد لا تسبب أعراضًا حتى حدوث أول كسر، خاصة في الرسغ أو الحوض أو الفقرات.","يساعد قياس كثافة العظام على التشخيص المبكر وتقدير خطر الكسور."]},{"title":"الأسباب المحتملة","icon":"searchCheck","items":["التقدم في العمر وانقطاع الطمث","نقص الكالسيوم وفيتامين د","قلة النشاط البدني","التدخين وبعض الأدوية مثل الكورتيزون لفترات طويلة"]},{"title":"متى تزور الطبيب؟","icon":"alertCircle","items":["كسر بعد سقطة بسيطة","ألم مفاجئ في الظهر أو نقص ملحوظ في الطول","وجود عوامل خطورة مثل التاريخ العائلي"]},{"title":"التشخيص والعلاج","icon":"clipboardCheck","paragraphs":["تشمل الخطة التغذية الغنية بالكالسيوم وفيتامين د، والتمارين المناسبة، والوقاية من السقوط، والعلاج الدوائي بحسب تقييم الطبيب."]}]},"details_en":{"lead":"Osteoporosis is a condition in which bone density falls and bone structure weakens, so bones break more easily — even after a minor fall.","sections":[{"title":"Overview","icon":"info","paragraphs":["It is sometimes called a “silent disease” because it may cause no symptoms until the first fracture, often in the wrist, hip or spine.","A bone density scan helps diagnose it early and estimate the risk of fractures."]},{"title":"Possible causes","icon":"searchCheck","items":["Older age and menopause","Too little calcium and vitamin D","Physical inactivity","Smoking and some medicines, such as long-term steroids"]},{"title":"When to see a doctor","icon":"alertCircle","items":["A fracture after a minor fall","Sudden back pain or a noticeable loss of height","Risk factors such as a family history"]},{"title":"Diagnosis and treatment","icon":"clipboardCheck","paragraphs":["The plan includes a diet rich in calcium and vitamin D, suitable exercise, fall prevention and medication as assessed by the doctor."]}]}}]$cms_seed$::jsonb)
on conflict (slug) do nothing;

