select "id", "slug", "icon", "service_id", "image_id", "sort_order", "status", "title_ar", "title_en", "description_ar", "description_en" from jsonb_populate_recordset(null::public.specialties, $cms_seed$[{"id":"21080773-7a20-52ad-8efb-e23462bd0444","slug":"knee-joints","icon":"bone","service_id":"239300f8-25fb-59e1-990a-c39a61d52d39","image_id":"90ad0c95-6456-50a8-b381-88337df06a12","sort_order":1,"status":"published","title_ar":"الركبة والمفاصل","title_en":"Knee and Joints","description_ar":"تقييم وعلاج آلام الركبة وخشونة المفاصل وإصابات الأربطة والغضاريف.","description_en":"Assessing and treating knee pain, osteoarthritis, and ligament and cartilage injuries."},{"id":"d4978344-ed6d-5a70-ba64-d8568a3176c9","slug":"spine","icon":"spine","service_id":"1d784415-a137-5e3d-8422-1ca3021bf58c","image_id":"1c65e949-ebaa-5099-9da8-9b2757d253bd","sort_order":2,"status":"published","title_ar":"العمود الفقري","title_en":"Spine","description_ar":"تشخيص آلام الظهر والرقبة والانزلاق الغضروفي، مع البدء بالعلاج التحفظي كلما أمكن.","description_en":"Diagnosing back and neck pain and herniated discs, starting with conservative treatment whenever possible."},{"id":"1bbbcd1c-89df-5ea4-aeef-310744499d92","slug":"sports-rehab","icon":"activity","service_id":"f2321bc9-07ef-5641-ba4b-f1e654480e3f","image_id":"2cbecefa-08fc-55a9-9aae-462451cac8fe","sort_order":3,"status":"published","title_ar":"الإصابات الرياضية والتأهيل","title_en":"Sports Injuries and Rehabilitation","description_ar":"متابعة الإصابة من التشخيص حتى العودة الآمنة إلى الملعب ببرنامج تأهيل تدريجي.","description_en":"Following an injury from diagnosis to a safe return to play, with a gradual rehabilitation program."},{"id":"1e903a65-bb6c-535c-bf25-0bd99e29ee8b","slug":"fractures-trauma","icon":"boneFracture","service_id":"d8fc90f1-eeb6-5838-b69c-b881fef7922f","image_id":"1a29f316-54d1-55d7-bcde-0c24f2ef2e7b","sort_order":4,"status":"published","title_ar":"الكسور والإصابات","title_en":"Fractures and Injuries","description_ar":"التعامل مع الكسور ومتابعة الالتئام، ثم استعادة الحركة والقوة بعد الإصابة.","description_en":"Managing fractures and monitoring healing, then restoring movement and strength after the injury."}]$cms_seed$::jsonb)
