select "id", "key", "rating", "avatar_id", "featured", "is_placeholder", "sort_order", "status", "name_ar", "name_en", "text_ar", "text_en", "context_ar", "context_en" from jsonb_populate_recordset(null::public.reviews, $cms_seed$[{"id":"89ac6a84-dc0c-5ddd-875d-b921c5607f49","key":"review-1","rating":5,"avatar_id":null,"featured":true,"is_placeholder":true,"sort_order":10,"status":"published","name_ar":"اسم المراجع ١","name_en":"Reviewer name 1","text_ar":"شرح واضح للحالة من أول زيارة، واهتمام حقيقي بكل تفصيلة في الشكوى. خرجت وأنا فاهم خطة العلاج وخطواتها.","text_en":"A clear explanation of my condition from the very first visit, and real attention to every detail of my complaint. I left understanding my treatment plan and each of its steps.","context_ar":"استشارة آلام الركبة","context_en":"Knee pain consultation"},{"id":"43b62c03-f0bb-51de-87f8-0ab8c4d48279","key":"review-2","rating":5,"avatar_id":null,"featured":true,"is_placeholder":true,"sort_order":20,"status":"published","name_ar":"اسم المراجع ٢","name_en":"Reviewer name 2","text_ar":"مواعيد منظمة وتعامل راقٍ من الفريق. الطبيب استمع جيدًا وأجاب عن كل أسئلتي بصبر ووضوح.","text_en":"Well-organized appointments and a courteous team. The doctor listened carefully and answered all my questions patiently and clearly.","context_ar":"متابعة آلام الظهر","context_en":"Back pain follow-up"},{"id":"b1f99948-2abf-5d43-a2b8-b4c856f92c24","key":"review-3","rating":5,"avatar_id":null,"featured":true,"is_placeholder":true,"sort_order":30,"status":"published","name_ar":"اسم المراجع ٣","name_en":"Reviewer name 3","text_ar":"بعد إصابتي في التمرين كنت قلقًا من العودة للرياضة، والمتابعة كانت مطمئنة ومنظمة خطوة بخطوة.","text_en":"After my training injury I was worried about getting back to sport, and the follow-up was reassuring and organized step by step.","context_ar":"إصابة رياضية","context_en":"Sports injury"},{"id":"9b449241-801b-5669-a917-230e5f53cbad","key":"review-4","rating":4,"avatar_id":null,"featured":true,"is_placeholder":true,"sort_order":40,"status":"published","name_ar":"اسم المراجع ٤","name_en":"Reviewer name 4","text_ar":"تجربة مريحة وخطة واضحة، وأعجبني أن المتابعة لم تتوقف بعد الزيارة الأولى.","text_en":"A comfortable experience and a clear plan, and I liked that the follow-up didn't stop after the first visit.","context_ar":"استشارة آلام الكتف","context_en":"Shoulder pain consultation"},{"id":"cb443924-9bd5-5e77-bcfe-4eecdf8d6b1d","key":"review-5","rating":5,"avatar_id":null,"featured":false,"is_placeholder":true,"sort_order":50,"status":"published","name_ar":"اسم المراجع ٥","name_en":"Reviewer name 5","text_ar":"الطبيب شرح لي نتيجة الأشعة بالتفصيل وبلغة بسيطة، ووضّح ما أحتاجه فعلًا وما لا أحتاجه.","text_en":"The doctor went through my scan results in detail and in plain language, and made clear what I actually needed and what I didn't.","context_ar":"متابعة خشونة المفاصل","context_en":"Osteoarthritis follow-up"},{"id":"832aed56-3a23-5113-9da6-fdd550cca789","key":"review-6","rating":5,"avatar_id":null,"featured":false,"is_placeholder":true,"sort_order":60,"status":"published","name_ar":"اسم المراجع ٦","name_en":"Reviewer name 6","text_ar":"بعد الكسر كنت قلقًا من طول فترة التعافي، لكن كل مرحلة كانت واضحة ومعروفة مسبقًا، وهذا طمأنني كثيرًا.","text_en":"After my fracture I was worried about a long recovery, but every stage was clear and explained in advance, which reassured me a lot.","context_ar":"متابعة كسر في الرسغ","context_en":"Wrist fracture follow-up"},{"id":"8ed22a61-c40c-5464-bb8a-f271644c4e1a","key":"review-7","rating":4,"avatar_id":null,"featured":false,"is_placeholder":true,"sort_order":70,"status":"published","name_ar":"اسم المراجع ٧","name_en":"Reviewer name 7","text_ar":"حجز سهل عبر واتساب ورد سريع على الاستفسارات. الانتظار في العيادة كان قصيرًا والتنظيم جيد.","text_en":"Easy booking on WhatsApp and quick replies to my questions. The wait at the clinic was short and everything was well organized.","context_ar":"استشارة آلام الظهر","context_en":"Back pain consultation"},{"id":"015617f0-fcea-5371-a105-c823968320b0","key":"review-8","rating":5,"avatar_id":null,"featured":false,"is_placeholder":true,"sort_order":80,"status":"published","name_ar":"اسم المراجع ٨","name_en":"Reviewer name 8","text_ar":"أكثر ما أعجبني أن الطبيب أشركني في اختيار خطة العلاج، وشرح الخيارات المتاحة ومميزات كل خيار.","text_en":"What I liked most was that the doctor involved me in choosing my treatment plan and explained the options and the benefits of each.","context_ar":"استشارة آلام الركبة","context_en":"Knee pain consultation"}]$cms_seed$::jsonb)
on conflict (key) do nothing;

-- faqs (10)
insert into public.faqs ("id", "key", "featured", "sort_order", "status", "question_ar", "question_en", "answer_ar", "answer_en")
select "id", "key", "featured", "sort_order", "status", "question_ar", "question_en", "answer_ar", "answer_en" from jsonb_populate_recordset(null::public.faqs, $cms_seed$[{"id":"ceca8fdb-45e6-5238-ad3b-64472e38c829","key":"faq-booking","featured":true,"sort_order":10,"status":"published","question_ar":"كيف يمكنني حجز موعد؟","question_en":"How can I book an appointment?","answer_ar":"يمكنك الحجز عبر الاتصال الهاتفي أو من خلال واتساب، وسيتم تأكيد الموعد المناسب لك مع توضيح أي تعليمات قبل الزيارة.","answer_en":"You can book by phone or on WhatsApp. We'll confirm a time that suits you and let you know about any instructions before your visit."},{"id":"850e1cd2-3788-55e8-a889-bc14c48306a3","key":"faq-first-visit","featured":true,"sort_order":20,"status":"published","question_ar":"ماذا أُحضر معي في الزيارة الأولى؟","question_en":"What should I bring to my first visit?","answer_ar":"يُفضّل إحضار أي أشعة أو تحاليل سابقة، وقائمة بالأدوية التي تتناولها، وأي تقارير طبية متعلقة بالشكوى الحالية.","answer_en":"Please bring any previous X-rays or test results, a list of the medicines you take, and any medical reports related to your current complaint."},{"id":"2822d498-f45a-56bb-8ba2-541a11f07549","key":"faq-duration","featured":true,"sort_order":30,"status":"published","question_ar":"كم تستغرق الاستشارة؟","question_en":"How long does a consultation take?","answer_ar":"تختلف مدة الاستشارة حسب طبيعة الحالة، والهدف دائمًا أن تحصل على وقت كافٍ لشرح شكواك وفهم خطة العلاج.","answer_en":"It depends on your condition. The aim is always to give you enough time to explain your complaint and understand your treatment plan."},{"id":"976235cc-fdcb-571a-a8c9-4500f0240ce3","key":"faq-imaging","featured":true,"sort_order":40,"status":"published","question_ar":"هل أحتاج إلى أشعة قبل الزيارة؟","question_en":"Do I need an X-ray before my visit?","answer_ar":"ليس بالضرورة؛ يحدد الطبيب بعد الفحص السريري ما إذا كانت هناك حاجة لأشعة أو فحوصات إضافية.","answer_en":"Not necessarily. After examining you, the doctor will decide whether you need X-rays or any other tests."},{"id":"cb1a8766-6f64-5f6d-867c-4827e76b6e51","key":"faq-follow-up","featured":true,"sort_order":50,"status":"published","question_ar":"كيف تتم المتابعة بعد بدء العلاج؟","question_en":"How does follow-up work once treatment starts?","answer_ar":"يتم تحديد مواعيد المتابعة وفق خطة العلاج، مع تقييم التقدم وتعديل الخطة عند الحاجة.","answer_en":"Follow-up visits are scheduled according to your treatment plan, to review your progress and adjust the plan when needed."},{"id":"3a7b70e6-3ddf-58f4-bcfb-2ca5fe9e9a78","key":"faq-whatsapp","featured":true,"sort_order":60,"status":"published","question_ar":"هل يمكنني التواصل عبر واتساب؟","question_en":"Can I contact you on WhatsApp?","answer_ar":"نعم، يمكنك إرسال استفسارك أو طلب الحجز عبر واتساب، وسيتم الرد عليك في أقرب وقت ممكن.","answer_en":"Yes. You can send your question or booking request on WhatsApp, and we'll reply as soon as possible."},{"id":"1fbc9e39-7e51-524b-9a73-0bcf16de7b25","key":"faq-reschedule","featured":false,"sort_order":70,"status":"published","question_ar":"هل يمكنني تغيير موعدي أو إلغاؤه؟","question_en":"Can I change or cancel my appointment?","answer_ar":"نعم، يُرجى إبلاغنا مسبقًا عبر الهاتف أو واتساب حتى نتمكن من إعادة جدولة الموعد في وقت يناسبك.","answer_en":"Yes. Please let us know in advance by phone or WhatsApp so we can rebook your appointment at a time that suits you."},{"id":"a3458887-f5d6-5b0a-85ee-55ec979cff66","key":"faq-physiotherapy","featured":false,"sort_order":80,"status":"published","question_ar":"هل سأحتاج إلى علاج طبيعي؟","question_en":"Will I need physiotherapy?","answer_ar":"يحدد الطبيب الحاجة إلى العلاج الطبيعي بحسب الحالة، وغالبًا يكون جزءًا مهمًا من خطة التعافي بعد الإصابات وفي حالات آلام الظهر والمفاصل.","answer_en":"The doctor decides whether you need physiotherapy based on your condition. It is often an important part of recovery after injuries and for back and joint pain."},{"id":"e379dffa-9186-54ad-9686-dc1b25eac927","key":"faq-sport-pain","featured":false,"sort_order":90,"status":"published","question_ar":"هل أتوقف عن الرياضة إذا شعرت بألم؟","question_en":"Should I stop exercising if I feel pain?","answer_ar":"يُنصح بتخفيف النشاط المسبب للألم وعدم الاستمرار فيه، وطلب التقييم إذا استمر الألم أو صاحبه تورّم أو شعور بعدم ثبات المفصل.","answer_en":"It's best to ease off the activity that causes the pain rather than push through it, and to get assessed if the pain persists or comes with swelling or a feeling that the joint is unstable."},{"id":"059fe995-5747-5976-930b-5fe6c1c84081","key":"faq-remote","featured":false,"sort_order":100,"status":"published","question_ar":"هل يمكن متابعة حالتي دون زيارة العيادة؟","question_en":"Can my condition be followed up without visiting the clinic?","answer_ar":"يمكنك الاستفسار عبر واتساب، ويحدد الطبيب ما إذا كانت حالتك تسمح بالمتابعة عن بُعد أم تحتاج إلى زيارة حضورية وفحص سريري.","answer_en":"You can ask on WhatsApp, and the doctor will decide whether your condition can be followed up remotely or needs an in-person visit and examination."}]$cms_seed$::jsonb)
on conflict (key) do nothing;

