select "id", "key", "sort_order", "name_ar", "name_en" from jsonb_populate_recordset(null::public.article_categories, $cms_seed$[{"id":"7caf3ff9-6a5d-5317-ab51-83b3fb909b5a","key":"joint-health","sort_order":10,"name_ar":"صحة المفاصل","name_en":"Joint health"},{"id":"f12584fc-16bd-5b1a-ac51-2810a5e5eba5","key":"spine","sort_order":20,"name_ar":"العمود الفقري","name_en":"Spine"},{"id":"213fc525-2fc8-55b3-85bb-d898f5c0c913","key":"sports-injuries","sort_order":30,"name_ar":"الإصابات الرياضية","name_en":"Sports injuries"},{"id":"bbb4daa8-f699-596c-8b22-d86166043641","key":"bone-health","sort_order":40,"name_ar":"صحة العظام","name_en":"Bone health"},{"id":"db9719ca-e461-5add-9bbb-4d6a88afa02d","key":"lifestyle","sort_order":50,"name_ar":"نمط الحياة","name_en":"Lifestyle"},{"id":"d3a2f436-186c-5569-a163-4feea9f669a7","key":"rehabilitation-and-physiotherapy","sort_order":60,"name_ar":"التأهيل والعلاج الطبيعي","name_en":"Rehabilitation and physiotherapy"},{"id":"f70942f0-b052-5ba7-9037-26280b94856c","key":"tests-and-imaging","sort_order":70,"name_ar":"الفحوصات والأشعة","name_en":"Tests and imaging"}]$cms_seed$::jsonb)
