-- articles (7)
insert into public.articles ("id", "slug", "published_at", "category_id", "cover_id", "featured", "sort_order", "status", "title_ar", "title_en", "excerpt_ar", "excerpt_en", "body_ar", "body_en")
select "id", "slug", "published_at", "category_id", "cover_id", "featured", "sort_order", "status", "title_ar", "title_en", "excerpt_ar", "excerpt_en", "body_ar", "body_en" from jsonb_populate_recordset(null::public.articles, $cms_seed$[{"id":"acf65763-d684-5eb7-95fb-066763f3d237","slug":"knee-osteoarthritis","published_at":"2026-09-18","category_id":"7caf3ff9-6a5d-5317-ab51-83b3fb909b5a","cover_id":"e1fe9f49-34af-5a40-b3b0-4233902670a5","featured":true,"sort_order":1,"status":"published","title_ar":"خشونة الركبة: الأعراض المبكرة وطرق التعامل معها","title_en":"Knee Osteoarthritis: Early Symptoms and How to Manage Them","excerpt_ar":"دليل مبسّط لفهم خشونة الركبة: كيف تبدأ، وما العلامات المبكرة التي لا يجب تجاهلها، وما الذي يمكنك فعله يوميًا لتخفيف الألم والحفاظ على الحركة.","excerpt_en":"A simple guide to knee osteoarthritis: how it starts, the early signs you shouldn't ignore, and what you can do every day to ease the pain and stay mobile.","body_ar":[{"type":"paragraph","text":"خشونة الركبة من أكثر مشكلات المفاصل شيوعًا، خاصة بعد سن الأربعين. تحدث عندما يتآكل الغضروف الذي يغطي أطراف العظام داخل المفصل تدريجيًا، فيفقد المفصل جزءًا من نعومته وقدرته على امتصاص الصدمات."},{"type":"heading","text":"كيف تبدأ خشونة الركبة؟"},{"type":"paragraph","text":"تتطور الخشونة ببطء على مدار سنوات. في البداية قد لا يلاحظ المريض سوى ألم خفيف بعد المجهود أو صعود السلم، ثم تظهر أعراض أوضح مع تقدم الحالة."},{"type":"heading","text":"العلامات المبكرة"},{"type":"list","items":["ألم في الركبة يزداد مع المشي الطويل أو صعود السلم ويخف مع الراحة","تيبّس صباحي أو بعد الجلوس لفترة، يتحسن خلال دقائق من الحركة","صوت طقطقة أو احتكاك عند ثني الركبة","تورّم خفيف متكرر حول المفصل"]},{"type":"heading","text":"عوامل تزيد من خطر الإصابة"},{"type":"list","items":["التقدم في العمر","زيادة الوزن، إذ يتضاعف الحمل على الركبة مع كل خطوة","إصابات سابقة في الركبة مثل تمزق الغضروف أو الأربطة","ضعف العضلات المحيطة بالركبة","العوامل الوراثية"]},{"type":"heading","text":"ماذا يمكنك أن تفعل يوميًا؟"},{"type":"list","ordered":true,"items":["حافظ على نشاطك؛ فالمشي المعتدل والسباحة وركوب الدراجة الثابتة أنشطة مناسبة لمعظم المرضى","قوِّ عضلات الفخذ بتمارين بسيطة، فهي تخفف الحمل عن المفصل","حافظ على وزن صحي؛ فحتى نقصان بضعة كيلوجرامات قد يخفف الألم","استخدم حذاءً مريحًا يدعم القدم","وزّع المجهود على اليوم وتجنّب الوقوف أو الجلوس لفترات طويلة جدًا"]},{"type":"callout","tone":"tip","title":"نصيحة","text":"لا تتوقف عن الحركة تمامًا بسبب الألم؛ فقلة الحركة تُضعف العضلات وتزيد التيبّس. اختر نشاطًا مناسبًا وابدأ تدريجيًا."},{"type":"heading","text":"متى تزور الطبيب؟"},{"type":"paragraph","text":"يُنصح بالتقييم إذا استمر الألم أكثر من بضعة أسابيع، أو صاحبه تورّم متكرر، أو أثّر على نومك أو قدرتك على المشي. يساعد الفحص السريري والأشعة على تحديد درجة الخشونة ووضع خطة علاج مناسبة قد تشمل التمارين العلاجية والأدوية، إلى جانب خيارات أخرى في الحالات المتقدمة."}],"body_en":[{"type":"paragraph","text":"Knee osteoarthritis is one of the most common joint problems, especially after the age of forty. It happens when the cartilage that covers the ends of the bones inside the joint gradually wears away, so the joint loses some of its smoothness and its ability to absorb shock."},{"type":"heading","text":"How does knee osteoarthritis start?"},{"type":"paragraph","text":"Osteoarthritis develops slowly over years. At first you may notice only mild pain after exertion or climbing stairs; clearer symptoms appear as the condition progresses."},{"type":"heading","text":"Early signs"},{"type":"list","items":["Knee pain that gets worse with long walks or stairs and eases with rest","Stiffness in the morning or after sitting for a while that improves within minutes of moving","A clicking or grinding sound when you bend the knee","Mild swelling around the joint that keeps coming back"]},{"type":"heading","text":"What raises the risk?"},{"type":"list","items":["Getting older","Excess weight, since every step multiplies the load on the knee","Previous knee injuries, such as a meniscus or ligament tear","Weak muscles around the knee","Genetic factors"]},{"type":"heading","text":"What can you do every day?"},{"type":"list","ordered":true,"items":["Stay active: moderate walking, swimming and stationary cycling suit most people","Strengthen your thigh muscles with simple exercises — they take load off the joint","Keep to a healthy weight; even losing a few kilograms can ease the pain","Wear comfortable, supportive shoes","Spread your activity through the day and avoid very long spells of standing or sitting"]},{"type":"callout","tone":"tip","title":"Tip","text":"Don't stop moving altogether because of pain — inactivity weakens the muscles and makes stiffness worse. Choose a suitable activity and build up gradually."},{"type":"heading","text":"When should you see a doctor?"},{"type":"paragraph","text":"It's worth getting assessed if the pain lasts more than a few weeks, keeps coming back with swelling, or affects your sleep or your ability to walk. A clinical examination and X-rays show how advanced the osteoarthritis is and help set a suitable treatment plan, which may include therapeutic exercise and medication, with other options in advanced cases."}]},{"id":"7b2eda93-b1cf-555f-b72d-b3261a47bb20","slug":"lower-back-pain","published_at":"2026-09-04","category_id":"f12584fc-16bd-5b1a-ac51-2810a5e5eba5","cover_id":"700a166a-f114-54f7-8e58-ecccf55e37b0","featured":false,"sort_order":2,"status":"published","title_ar":"آلام أسفل الظهر: الأسباب الشائعة ومتى تقلق","title_en":"Lower Back Pain: Common Causes and When to Worry","excerpt_ar":"معظم حالات آلام أسفل الظهر بسيطة وتتحسن خلال أسابيع، لكن هناك علامات تستدعي التقييم الطبي. تعرّف على الأسباب الشائعة وخطوات التعامل الصحيح.","excerpt_en":"Most lower back pain is minor and improves within weeks, but some signs call for a medical assessment. Learn the common causes and the right steps to take.","body_ar":[{"type":"paragraph","text":"يعاني أغلب الناس من ألم أسفل الظهر في مرحلة ما من حياتهم. والخبر الجيد أن معظم الحالات ترتبط بإجهاد العضلات أو الأربطة، وتتحسن تدريجيًا مع الحركة المناسبة والعناية البسيطة."},{"type":"heading","text":"أسباب شائعة"},{"type":"list","items":["شد عضلي بعد حمل شيء ثقيل أو حركة مفاجئة","الجلوس لفترات طويلة بوضعية غير صحيحة","ضعف عضلات البطن والظهر","الانزلاق الغضروفي","التغيرات المرتبطة بالعمر في الفقرات والغضاريف"]},{"type":"heading","text":"ماذا تفعل في الأيام الأولى؟"},{"type":"list","ordered":true,"items":["تجنّب الراحة التامة في السرير؛ فالحركة الخفيفة تساعد على التعافي أسرع","استخدم الكمادات الدافئة لتخفيف تقلص العضلات","عدّل الأنشطة المؤلمة مؤقتًا بدلًا من إيقاف نشاطك كله","استشر الطبيب قبل تناول أي مسكنات، خاصة إذا كانت لديك أمراض مزمنة"]},{"type":"callout","tone":"warning","title":"علامات تستدعي التقييم العاجل","text":"توجّه إلى الطبيب فورًا إذا صاحب ألم الظهر ضعف متزايد في الساقين، أو تنميل في منطقة الحوض، أو صعوبة في التحكم في البول أو البراز، أو حرارة غير مفسَّرة، أو إذا بدأ الألم بعد سقوط أو حادث."},{"type":"heading","text":"الوقاية خير من العلاج"},{"type":"paragraph","text":"تساعد تمارين تقوية عضلات الجذع، والحفاظ على وزن صحي، وأخذ فترات قصيرة للحركة أثناء العمل المكتبي، ورفع الأشياء بثني الركبتين بدلًا من انحناء الظهر، على تقليل فرص تكرار الألم."},{"type":"heading","text":"متى تحتاج إلى زيارة طبيب العظام؟"},{"type":"paragraph","text":"إذا استمر الألم أكثر من أربعة إلى ستة أسابيع رغم العناية المنزلية، أو كان يمتد إلى الساق، أو يتكرر بشكل يؤثر على عملك وحياتك اليومية، فالتقييم الطبي يساعد على معرفة السبب ووضع خطة علاج مناسبة."}],"body_en":[{"type":"paragraph","text":"Most people have lower back pain at some point in their lives. The good news is that most cases are linked to strained muscles or ligaments, and they improve gradually with the right kind of movement and simple care."},{"type":"heading","text":"Common causes"},{"type":"list","items":["A muscle strain after lifting something heavy or a sudden movement","Sitting for long periods in a poor posture","Weak abdominal and back muscles","A herniated disc","Age-related changes in the vertebrae and discs"]},{"type":"heading","text":"What to do in the first few days"},{"type":"list","ordered":true,"items":["Avoid complete bed rest — gentle movement helps you recover faster","Use warm compresses to relax tight muscles","Modify painful activities for a while instead of stopping everything","Check with your doctor before taking painkillers, especially if you have a long-term condition"]},{"type":"callout","tone":"warning","title":"Signs that need urgent assessment","text":"See a doctor immediately if back pain comes with increasing weakness in your legs, numbness around the pelvis, difficulty controlling your bladder or bowels, an unexplained fever, or if the pain started after a fall or accident."},{"type":"heading","text":"Prevention is better than cure"},{"type":"paragraph","text":"Strengthening your core muscles, keeping to a healthy weight, taking short movement breaks during desk work, and lifting with your knees bent rather than bending your back all help reduce the chance of the pain coming back."},{"type":"heading","text":"When should you see an orthopedic doctor?"},{"type":"paragraph","text":"If the pain lasts more than four to six weeks despite care at home, spreads down your leg, or keeps returning in a way that affects your work and daily life, a medical assessment helps find the cause and set a suitable treatment plan."}]},{"id":"72e92425-3717-50b9-ac90-cd162d8d59f8","slug":"sports-first-aid","published_at":"2026-08-21","category_id":"213fc525-2fc8-55b3-85bb-d898f5c0c913","cover_id":"9614556b-da9f-5d77-b704-103676f53c4d","featured":false,"sort_order":3,"status":"published","title_ar":"الإسعافات الأولية للإصابات الرياضية: ماذا تفعل في الدقائق الأولى؟","title_en":"First Aid for Sports Injuries: What to Do in the First Few Minutes","excerpt_ar":"الدقائق الأولى بعد الإصابة الرياضية تصنع فرقًا في التعافي. خطوات عملية للتعامل مع الالتواءات والكدمات، ومتى يجب التوقف وطلب التقييم.","excerpt_en":"The first minutes after a sports injury make a real difference to recovery. Practical steps for sprains and bruises, and when to stop and get checked.","body_ar":[{"type":"paragraph","text":"تحدث الإصابات الرياضية في أي مستوى من ممارسة الرياضة، من المباريات الودية إلى المنافسات. والتعامل الصحيح في الدقائق الأولى يقلل التورم والألم ويساعد على تعافٍ أفضل."},{"type":"heading","text":"أوقف النشاط فورًا"},{"type":"paragraph","text":"الاستمرار في اللعب بعد الإصابة قد يحوّل إصابة بسيطة إلى إصابة أشد. إذا شعرت بألم مفاجئ أو سمعت صوت فرقعة أو فقدت الثقة في ثبات المفصل، فتوقف واطلب التقييم."},{"type":"heading","text":"خطوات الإسعاف الأولي للالتواءات والكدمات"},{"type":"list","ordered":true,"items":["الراحة: أوقف تحميل الوزن على الطرف المصاب","الثلج: ضع كمادة باردة ملفوفة بقطعة قماش لمدة 15 إلى 20 دقيقة، وكرر ذلك كل بضع ساعات في اليوم الأول","الضغط: استخدم رباطًا ضاغطًا بشكل معتدل دون إحكام زائد","الرفع: ارفع الطرف المصاب فوق مستوى القلب لتقليل التورم"]},{"type":"callout","tone":"tip","title":"لا تضع الثلج مباشرة على الجلد","text":"لفّ الثلج دائمًا بقطعة قماش لتجنب إصابة الجلد بالبرودة، ولا تتجاوز المدة الموصى بها في كل مرة."},{"type":"heading","text":"علامات تستدعي زيارة الطبيب"},{"type":"list","items":["صعوبة في المشي أو تحميل الوزن بعد الإصابة","تشوّه واضح في شكل المفصل أو العظم","تورّم شديد وسريع","تنميل أو برودة في الطرف المصاب","ألم لا يتحسن خلال أيام"]},{"type":"heading","text":"العودة إلى الملعب"},{"type":"paragraph","text":"لا تعتمد على اختفاء الألم وحده علامةً للعودة. تحتاج العضلات والأربطة إلى استعادة قوتها ومرونتها وتوازنها أولًا، ويساعد برنامج التأهيل التدريجي على العودة الآمنة وتقليل احتمال تكرار الإصابة."}],"body_en":[{"type":"paragraph","text":"Sports injuries happen at every level of play, from friendly matches to competitions. Handling them correctly in the first few minutes reduces swelling and pain and supports a better recovery."},{"type":"heading","text":"Stop playing straight away"},{"type":"paragraph","text":"Playing on after an injury can turn a minor problem into a more serious one. If you feel sudden pain, hear a pop or no longer trust a joint to hold, stop and get it assessed."},{"type":"heading","text":"First aid for sprains and bruises"},{"type":"list","ordered":true,"items":["Rest: stop putting weight on the injured limb","Ice: apply a cold pack wrapped in a cloth for 15 to 20 minutes, and repeat every few hours on the first day","Compression: use a compression bandage firmly, but not too tightly","Elevation: raise the injured limb above the level of your heart to reduce swelling"]},{"type":"callout","tone":"tip","title":"Never put ice directly on the skin","text":"Always wrap ice in a cloth to avoid a cold injury to the skin, and don't go beyond the recommended time for each application."},{"type":"heading","text":"Signs that you need to see a doctor"},{"type":"list","items":["Difficulty walking or putting weight on the limb after the injury","An obvious deformity of the joint or bone","Severe, rapid swelling","Numbness or coldness in the injured limb","Pain that doesn't improve within a few days"]},{"type":"heading","text":"Getting back to play"},{"type":"paragraph","text":"Don't rely on the pain going away as your only sign that you're ready. Your muscles and ligaments first need to regain their strength, flexibility and balance, and a gradual rehabilitation program helps you return safely and lowers the risk of re-injury."}]},{"id":"545205d6-d30d-5844-9d7e-909758ea1caf","slug":"bone-health","published_at":"2026-08-07","category_id":"bbb4daa8-f699-596c-8b22-d86166043641","cover_id":"260a73e2-ffb2-5110-92ff-64d149e5c77a","featured":false,"sort_order":4,"status":"published","title_ar":"هشاشة العظام: كيف تحمي عظامك في كل مرحلة عمرية؟","title_en":"Osteoporosis: How to Protect Your Bones at Every Age","excerpt_ar":"هشاشة العظام لا تظهر أعراضها غالبًا إلا مع أول كسر. تعرّف على عوامل الخطورة، ودور التغذية والنشاط البدني، ومتى يُنصح بقياس كثافة العظام.","excerpt_en":"Osteoporosis often shows no symptoms until the first fracture. Learn about the risk factors, the role of diet and exercise, and when a bone density scan is recommended.","body_ar":[{"type":"paragraph","text":"تُبنى كتلة العظام خلال مرحلتي الطفولة والشباب، ثم تبدأ في التناقص تدريجيًا مع التقدم في العمر. وعندما يزداد هذا التناقص تصبح العظام أضعف وأكثر عرضة للكسر، وهي الحالة المعروفة بهشاشة العظام."},{"type":"heading","text":"لماذا تُسمّى «المرض الصامت»؟"},{"type":"paragraph","text":"لأنها غالبًا لا تسبب ألمًا أو أعراضًا واضحة حتى يحدث كسر، وكثيرًا ما يكون في الرسغ أو الحوض أو فقرات الظهر، وأحيانًا بعد سقطة بسيطة."},{"type":"heading","text":"عوامل تزيد من خطر الهشاشة"},{"type":"list","items":["التقدم في العمر، خاصة لدى السيدات بعد انقطاع الطمث","التاريخ العائلي للهشاشة أو كسور الحوض","نقص الكالسيوم وفيتامين د","قلة النشاط البدني","التدخين","استخدام بعض الأدوية مثل الكورتيزون لفترات طويلة"]},{"type":"heading","text":"خطوات لحماية عظامك"},{"type":"list","ordered":true,"items":["احرص على مصادر الكالسيوم في غذائك مثل الألبان والخضروات الورقية","تعرّض لأشعة الشمس باعتدال، واسأل طبيبك عن حاجتك إلى مكملات فيتامين د","مارس تمارين تحمّل الوزن مثل المشي وتمارين المقاومة الخفيفة","تجنّب التدخين وقلّل من المشروبات الغنية بالكافيين","اجعل منزلك آمنًا من السقوط: إضاءة جيدة وأرضيات غير زلقة"]},{"type":"callout","tone":"tip","title":"قياس كثافة العظام","text":"يساعد فحص كثافة العظام على اكتشاف الهشاشة مبكرًا قبل حدوث الكسور. اسأل طبيبك عن التوقيت المناسب لإجرائه بحسب عمرك وعوامل الخطورة لديك."},{"type":"heading","text":"العلاج ممكن"},{"type":"paragraph","text":"إذا ثبت وجود هشاشة، فهناك خطط علاجية تجمع بين التغذية والتمارين والأدوية المناسبة بحسب تقييم الطبيب، بهدف تقليل خطر الكسور والحفاظ على جودة الحياة."}],"body_en":[{"type":"paragraph","text":"Bone mass is built up during childhood and early adulthood, and then slowly declines with age. When that decline speeds up, bones become weaker and more likely to break — the condition known as osteoporosis."},{"type":"heading","text":"Why is it called a “silent disease”?"},{"type":"paragraph","text":"Because it often causes no pain or obvious symptoms until a bone breaks — often in the wrist, hip or spine, sometimes after only a minor fall."},{"type":"heading","text":"What raises the risk of osteoporosis?"},{"type":"list","items":["Getting older, especially for women after menopause","A family history of osteoporosis or hip fractures","Too little calcium and vitamin D","Physical inactivity","Smoking","Long-term use of some medicines, such as steroids"]},{"type":"heading","text":"Steps to protect your bones"},{"type":"list","ordered":true,"items":["Include calcium-rich foods in your diet, such as dairy products and leafy greens","Get moderate sun exposure, and ask your doctor whether you need vitamin D supplements","Do weight-bearing exercise such as walking and light resistance training","Avoid smoking and cut down on high-caffeine drinks","Make your home safer from falls, with good lighting and non-slip floors"]},{"type":"callout","tone":"tip","title":"Bone density scans","text":"A bone density scan helps detect osteoporosis early, before any fractures happen. Ask your doctor when it's right for you based on your age and risk factors."},{"type":"heading","text":"Treatment is possible"},{"type":"paragraph","text":"If osteoporosis is confirmed, treatment plans combine diet, exercise and suitable medication, as assessed by the doctor, to lower the risk of fractures and maintain quality of life."}]},{"id":"cc10fc99-7352-55bd-9948-2e8ce9176407","slug":"sitting-posture","published_at":"2026-07-24","category_id":"db9719ca-e461-5add-9bbb-4d6a88afa02d","cover_id":"2802af5a-dfb6-5689-8d97-1d4720cf14b4","featured":false,"sort_order":5,"status":"published","title_ar":"الجلوس الصحيح أمام المكتب: دليل عملي لحماية ظهرك ورقبتك","title_en":"Sitting Well at Your Desk: A Practical Guide to Protecting Your Back and Neck","excerpt_ar":"ساعات العمل الطويلة أمام الشاشة من أهم أسباب آلام الظهر والرقبة. تعديلات بسيطة في مكان عملك وعاداتك اليومية قد تصنع فرقًا كبيرًا.","excerpt_en":"Long hours at a screen are a major cause of back and neck pain. Simple changes to your workspace and daily habits can make a big difference.","body_ar":[{"type":"paragraph","text":"يقضي كثير منا ساعات طويلة يوميًا أمام الحاسوب أو الهاتف، ومع الوقت قد تتحول الوضعيات الخاطئة إلى ألم مزمن في الرقبة والكتفين وأسفل الظهر."},{"type":"heading","text":"اضبط مكان عملك"},{"type":"list","items":["اجعل أعلى الشاشة في مستوى العين أو أقل قليلًا، وعلى بُعد ذراع تقريبًا","اختر كرسيًا يدعم أسفل الظهر، أو ضع وسادة صغيرة خلفه","اجعل القدمين مستويتين على الأرض والركبتين بزاوية قريبة من القائمة","ضع لوحة المفاتيح والفأرة قريبتين بحيث يبقى المرفقان بجانب الجسم","إذا كنت تستخدم حاسوبًا محمولًا لفترات طويلة، فاستخدم حاملًا ولوحة مفاتيح منفصلة"]},{"type":"heading","text":"قاعدة الحركة المنتظمة"},{"type":"paragraph","text":"أفضل وضعية هي الوضعية التالية؛ فالجسم لا يحب الثبات الطويل حتى في الوضع الصحيح. غيّر وضعيتك باستمرار، وخذ استراحة قصيرة للحركة كل 30 إلى 45 دقيقة."},{"type":"heading","text":"تمارين بسيطة أثناء العمل"},{"type":"list","ordered":true,"items":["أرجِع الذقن إلى الخلف بلطف مع إطالة الرقبة، وكرر ذلك عشر مرات","ارفع الكتفين نحو الأذنين ثم أرخِهما ببطء","اضمم لوحَي الكتف إلى الخلف لعدة ثوانٍ","قف وامشِ لدقيقتين أو اصعد بضع درجات من السلم"]},{"type":"callout","tone":"tip","title":"انتبه للهاتف","text":"النظر إلى الهاتف والرأس منحنٍ إلى الأمام يزيد الحمل على الرقبة. ارفع الهاتف إلى مستوى العين قدر الإمكان."},{"type":"heading","text":"متى تستشير الطبيب؟"},{"type":"paragraph","text":"إذا استمر الألم رغم تعديل وضعيات العمل، أو صاحبه تنميل في الذراعين أو صداع متكرر، فالتقييم الطبي يساعد على معرفة السبب وتحديد العلاج المناسب."}],"body_en":[{"type":"paragraph","text":"Many of us spend long hours every day at a computer or on our phones, and over time a poor posture can turn into lasting pain in the neck, shoulders and lower back."},{"type":"heading","text":"Set up your workspace"},{"type":"list","items":["Place the top of the screen at or slightly below eye level, about an arm's length away","Choose a chair that supports your lower back, or put a small cushion behind you","Keep your feet flat on the floor and your knees at roughly a right angle","Keep the keyboard and mouse close, so your elbows stay by your sides","If you use a laptop for long periods, add a stand and a separate keyboard"]},{"type":"heading","text":"Keep moving regularly"},{"type":"paragraph","text":"The best posture is your next one — the body doesn't like staying still for long, even in a good position. Change position often and take a short movement break every 30 to 45 minutes."},{"type":"heading","text":"Simple exercises at work"},{"type":"list","ordered":true,"items":["Gently draw your chin back to lengthen your neck, and repeat ten times","Lift your shoulders toward your ears, then slowly let them drop","Squeeze your shoulder blades together for a few seconds","Stand up and walk for two minutes, or climb a few stairs"]},{"type":"callout","tone":"tip","title":"Watch your phone posture","text":"Looking down at your phone with your head bent forward increases the load on your neck. Raise the phone to eye level whenever you can."},{"type":"heading","text":"When should you see a doctor?"},{"type":"paragraph","text":"If the pain continues after you've improved your work posture, or comes with numbness in your arms or frequent headaches, a medical assessment helps find the cause and the right treatment."}]},{"id":"809aaf60-23fa-53f0-a115-08c802fa4120","slug":"physiotherapy-recovery","published_at":"2026-07-10","category_id":"d3a2f436-186c-5569-a163-4feea9f669a7","cover_id":"7e744ae5-6069-5b81-a296-c25501d7bb2c","featured":false,"sort_order":6,"status":"published","title_ar":"العلاج الطبيعي بعد الإصابات: لماذا لا تكفي الراحة وحدها؟","title_en":"Physiotherapy After an Injury: Why Rest Alone Isn't Enough","excerpt_ar":"الراحة جزء من التعافي، لكنها ليست كل شيء. تعرّف على دور العلاج الطبيعي في استعادة الحركة والقوة، وكيف تستفيد من جلساتك إلى أقصى حد.","excerpt_en":"Rest is part of recovery, but it isn't everything. Learn how physiotherapy helps restore movement and strength, and how to get the most from your sessions.","body_ar":[{"type":"paragraph","text":"بعد الإصابة أو الكسر أو الجراحة، يظن كثيرون أن الراحة وحدها كافية للتعافي. لكن فترات السكون الطويلة قد تؤدي إلى ضعف العضلات وتيبّس المفاصل، وهنا يأتي دور العلاج الطبيعي."},{"type":"heading","text":"ماذا يقدّم العلاج الطبيعي؟"},{"type":"list","items":["استعادة مدى حركة المفصل تدريجيًا","تقوية العضلات التي ضعفت بسبب الإصابة أو قلة الحركة","تحسين التوازن والتحكم الحركي لتقليل احتمال تكرار الإصابة","تخفيف الألم بوسائل مختلفة يحددها المعالج","تعليمك تمارين منزلية تكمل الجلسات"]},{"type":"heading","text":"مراحل التأهيل"},{"type":"list","ordered":true,"items":["حماية المنطقة المصابة وتخفيف الألم والتورم","استعادة الحركة والمرونة","التقوية التدريجية","العودة إلى الأنشطة اليومية أو الرياضية"]},{"type":"paragraph","text":"تختلف مدة كل مرحلة بحسب نوع الإصابة وشدتها، ويحدد الطبيب والمعالج متى تكون جاهزًا للانتقال من مرحلة إلى أخرى."},{"type":"callout","tone":"tip","title":"التمارين المنزلية جزء أساسي","text":"الجلسات وحدها لا تكفي؛ فالتزامك بالتمارين المنزلية بين الجلسات من أهم عوامل نجاح التأهيل."},{"type":"heading","text":"كيف تستفيد أكثر من جلساتك؟"},{"type":"list","items":["التزم بمواعيد الجلسات والتمارين المنزلية","أخبر المعالج بأي ألم غير معتاد أثناء التمرين","لا تستعجل العودة إلى النشاط الكامل قبل الموعد المحدد","دوّن ملاحظاتك عن التحسن والصعوبات لمناقشتها في المتابعة"]}],"body_en":[{"type":"paragraph","text":"After an injury, a fracture or surgery, many people assume that rest alone will be enough to recover. But long periods of inactivity can weaken muscles and stiffen joints — and that is where physiotherapy comes in."},{"type":"heading","text":"What does physiotherapy offer?"},{"type":"list","items":["Gradually restoring the joint's range of motion","Strengthening muscles weakened by the injury or by inactivity","Improving balance and movement control to reduce the risk of re-injury","Relieving pain with techniques chosen by your therapist","Teaching you home exercises that build on your sessions"]},{"type":"heading","text":"The stages of rehabilitation"},{"type":"list","ordered":true,"items":["Protecting the injured area and easing pain and swelling","Restoring movement and flexibility","Gradual strengthening","Returning to daily or sporting activities"]},{"type":"paragraph","text":"How long each stage takes depends on the type and severity of the injury, and your doctor and therapist will decide when you're ready to move on to the next one."},{"type":"callout","tone":"tip","title":"Home exercises are essential","text":"Sessions alone aren't enough — keeping up your home exercises between sessions is one of the most important factors in a successful recovery."},{"type":"heading","text":"How to get the most from your sessions"},{"type":"list","items":["Keep to your session schedule and your home exercises","Tell your therapist about any unusual pain during exercise","Don't rush back to full activity before the agreed time","Note your progress and any difficulties to discuss at follow-up"]}]},{"id":"d59409ab-f357-55f0-b588-de6cfa580bac","slug":"mri-guide","published_at":"2026-06-26","category_id":"f70942f0-b052-5ba7-9037-26280b94856c","cover_id":"2712896b-e489-578a-be33-9742ec0fbca2","featured":false,"sort_order":7,"status":"published","title_ar":"متى تحتاج إلى أشعة الرنين المغناطيسي؟ دليل مبسّط للمريض","title_en":"When Do You Need an MRI? A Simple Guide for Patients","excerpt_ar":"ليست كل آلام العظام والمفاصل بحاجة إلى رنين مغناطيسي. تعرّف على الفرق بين أنواع الأشعة، ومتى يطلب الطبيب الرنين، وكيف تستعد له.","excerpt_en":"Not every bone or joint pain needs an MRI. Learn how the types of imaging differ, when your doctor may request an MRI, and how to prepare for one.","body_ar":[{"type":"paragraph","text":"مع انتشار الفحوصات الحديثة، يسأل كثير من المرضى عن أشعة الرنين المغناطيسي منذ الزيارة الأولى. لكن الفحص الأنسب يعتمد على الشكوى ونتيجة الفحص السريري، وليس كل ألم يحتاج إلى رنين."},{"type":"heading","text":"الفرق بين أنواع التصوير"},{"type":"list","items":["الأشعة العادية (السينية): الأنسب لتقييم العظام والكسور وخشونة المفاصل","الموجات الصوتية: مفيدة لتقييم بعض الأوتار والأنسجة القريبة من سطح الجلد","الرنين المغناطيسي: يوضح الأنسجة الرخوة بدقة، مثل الغضاريف والأربطة والأقراص بين الفقرات والأعصاب","الأشعة المقطعية: تعطي تفاصيل دقيقة للعظام في حالات معينة"]},{"type":"heading","text":"متى يطلب الطبيب الرنين؟"},{"type":"list","items":["الاشتباه في إصابة الأربطة أو الغضاريف داخل المفصل","ألم في الظهر أو الرقبة مصحوب بعلامات عصبية كالتنميل أو الضعف","عدم التحسن رغم العلاج لفترة مناسبة","الحاجة إلى تخطيط دقيق قبل إجراء علاجي"]},{"type":"heading","text":"كيف تستعد لفحص الرنين؟"},{"type":"list","ordered":true,"items":["أخبر الطبيب إذا كان لديك منظم لضربات القلب أو أي أجهزة أو شظايا معدنية في الجسم","انزع المجوهرات والساعات والأغراض المعدنية قبل الفحص","أبلغ الفريق في حالة الحمل أو الخوف من الأماكن المغلقة","التزم بالثبات أثناء التصوير للحصول على صور واضحة"]},{"type":"callout","tone":"warning","title":"النتيجة تُقرأ مع الفحص السريري","text":"قد تظهر في الرنين تغيرات طبيعية مرتبطة بالعمر لا تسبب ألمًا، لذلك تُفسَّر النتائج دائمًا في ضوء الأعراض والفحص السريري، وليس بمعزل عنهما."},{"type":"paragraph","text":"إذا كانت لديك أشعة سابقة، فأحضرها معك في الزيارة؛ فقد تغني عن تكرار الفحص أو تساعد على مقارنة التغيرات."}],"body_en":[{"type":"paragraph","text":"With modern scans so widely available, many patients ask about an MRI at their very first visit. But the most suitable test depends on your complaint and on what the clinical examination finds — not every pain needs an MRI."},{"type":"heading","text":"How the types of imaging differ"},{"type":"list","items":["Plain X-rays: best for assessing bones, fractures and osteoarthritis","Ultrasound: useful for assessing some tendons and tissues close to the skin","MRI: shows soft tissues in detail, such as cartilage, ligaments, spinal discs and nerves","CT scans: give detailed images of bone in certain cases"]},{"type":"heading","text":"When might your doctor request an MRI?"},{"type":"list","items":["A suspected ligament or cartilage injury inside a joint","Back or neck pain with nerve-related signs such as numbness or weakness","No improvement despite an adequate period of treatment","The need for precise planning before a treatment procedure"]},{"type":"heading","text":"How to prepare for an MRI"},{"type":"list","ordered":true,"items":["Tell your doctor if you have a pacemaker, any implanted device or metal fragments in your body","Remove jewelry, watches and other metal items before the scan","Let the team know if you are pregnant or uneasy in enclosed spaces","Keep still during the scan so the images are clear"]},{"type":"callout","tone":"warning","title":"Results are read alongside the examination","text":"An MRI can show normal age-related changes that don't cause any pain, so results are always interpreted in light of your symptoms and the clinical examination — never on their own."},{"type":"paragraph","text":"If you have previous scans, bring them to your visit; they may spare you a repeat test or help compare changes over time."}]}]$cms_seed$::jsonb)
